const TEST_CENTERS = ['arorua.net', 'pearson.com'];
const FREE_MAIL = /^(gmail\.com|googlemail\.com|yahoo\.co\.jp|ymail\.ne\.jp|outlook\.(com|jp)|hotmail\.(com|co\.jp)|live\.jp|icloud\.com|me\.com|docomo\.ne\.jp|ezweb\.ne\.jp|au\.com|softbank\.ne\.jp|i\.softbank\.jp)$/;
const inDomains = (key, list) => list.some(d => key === d || key.endsWith('.' + d) || key.endsWith('@' + d));

const BLOCK_HEADER = ['送信元（ドメイン・アドレス・差出人の名前）', '読まない', 'メモ'];
const blockKey = s => normalize(s).trim().toLowerCase().replace(/^@/, '');

/**
 * 「読まない送信元」シート：1行に1つの送信元と、「読まない」のチェック。
 *   - 最初から主な就活サイトが書いてあり、チェックが入っている（読みたいサイトはチェックを外す）
 *   - あなたが行を足してもよい。送信元の書き方は3通り：
 *       ドメイン（example.jp）：そのドメインのメールを読まない（Gmailの検索の段階で除くので速い）
 *       アドレス（news@example.jp）：そのアドレスのメールを読まない
 *       差出人の名前（〇〇就活）：差出人の名前にその言葉があるメールを読まない
 * チェックが入っている送信元の一覧を返し、就活サイトの一覧（JOB_MEDIA）も決め直す
 */
function readBlocked(ss) {
  let sheet = ss.getSheetByName(CONFIG.BLOCK_SHEET);
  let entries = []; // [送信元, 読まない, メモ]
  if (sheet) {
    const values = sheet.getDataRange().getValues();
    const oldForm = headerKey(values[0][1]) !== headerKey(BLOCK_HEADER[1]); // 前の形（送信元・メモの2列）
    entries = values.slice(1).filter(r => blockKey(r[0]).length >= 2)
      // 「読まない」が空の行（あなたが送信元だけ書き足した行）は、読まないものとする
      .map(r => (oldForm ? [r[0], true, r[1] || ''] : [r[0], !(r[1] === false || String(r[1]).toUpperCase() === 'FALSE'), r[2] || '']));
    if (oldForm) sheet.clearContents();
  } else {
    sheet = ss.insertSheet(CONFIG.BLOCK_SHEET);
    sheet.setFrozenRows(1);
    sheet.setColumnWidth(1, 320);
  }
  // 最初から入れておく就活サイトで、まだシートにないものを足す（消しても次の更新で戻るので、読みたいときはチェックを外す）
  const known = new Set(entries.map(e => blockKey(e[0])));
  const added = DEFAULT_MEDIA.filter(([d]) => !known.has(d)).map(([d, name]) => [d, true, name]);
  const blank = entries.some(e => e[1] === true) && sheet.getLastRow() > 1 &&
    sheet.getRange(2, 2, sheet.getLastRow() - 1, 1).getValues().some(r => r[0] === ''); // チェック欄のない行がある
  if (added.length || blank || headerKey(sheet.getRange(1, 2).getValue()) !== headerKey(BLOCK_HEADER[1])) {
    entries = entries.concat(added);
    sheet.getRange(1, 1, 1, 3).setValues([BLOCK_HEADER]).setFontWeight('bold');
    sheet.getRange(2, 1, entries.length, 3).setValues(entries);
    sheet.getRange(2, 2, entries.length, 1).insertCheckboxes();
  }
  const blocked = entries.filter(e => e[1]).map(e => blockKey(e[0]));
  JOB_MEDIA = DEFAULT_MEDIA.map(m => m[0]).filter(d => blocked.includes(d));
  return blocked;
}

/** 読まない送信元か（就活サイトと「読まない送信元」シート） */
function isBlocked(from, blocked) {
  const addr = ((String(from).match(/<([^>]+)>/) || [0, String(from)])[1]).trim().toLowerCase();
  const name = normalize(from).replace(/<.*>/, '').replace(/"/g, '').toLowerCase();
  const key = senderKey(from);
  if (inDomains(key, JOB_MEDIA)) return true;
  return (blocked || []).some(b => (b.includes('@') ? addr === b
    : b.includes('.') ? inDomains(key, [b]) || addr.endsWith('@' + b) || addr.endsWith('.' + b)
      : name.includes(b)));
}

/** 差出人から送信元のキー（会社のドメイン。フリーメールはアドレス）を作る */
function senderKey(from) {
  const m = String(from).match(/<([^>]+)>/);
  const addr = (m ? m[1] : String(from)).trim().toLowerCase();
  const domain = addr.split('@')[1] || addr;
  if (FREE_MAIL.test(domain) || /(^|\.)google\.com$/.test(domain)) return addr;
  const parts = domain.split('.');
  const n = parts.length >= 3 && /^(co|ne|or|ac|go|ed|lg|gr|ad)$/.test(parts[parts.length - 2]) ? 3 : 2;
  return parts.slice(-n).join('.'); // mail.example.co.jp → example.co.jp
}

/** 送信元のドメインの名前の部分（freee.co.jp → freee）。共用のシステムやフリーメールは空 */
function domainLabel(sender) {
  if (!sender || sender.includes('@') || inDomains(sender, JOB_MEDIA) || inDomains(sender, SHARED_DOMAINS)) return '';
  const label = sender.split('.')[0];
  return label.length >= 3 && !/^(mail|info|recruit|saiyo|jinji|career|news|noreply|www)$/.test(label) ? label : '';
}

/** 会社名を比べるための形（「株式会社」や空白を除く） */
function companyKey(s) {
  // 「イグニション・ポイント」と「イグニションポイント」を同じと見るため、中黒などの記号も除く
  return normalize(s).replace(/株式会社|有限会社|合同会社|\(株\)|\s|[・･·.,、'’"&＆_\-]/g, '').toLowerCase();
}

/** メールの会社名：件名 → 差出人の名前 → 本文の最初 の順に「株式会社〇〇」を探す */
function extractCompany(subject, from, body) {
  const re = /(?:株式会社|有限会社|合同会社)\s*[^\s【】「」『』()\[\]、。:|]+|[^\s【】「」『』()\[\]、。:|]+(?:株式会社|有限会社|合同会社)/;
  const fromName = normalize(from).replace(/<.*>/, '').replace(/"/g, '');
  // 「株式会社〇〇新卒採用担当でございます」→「株式会社〇〇」
  const trimRole = s => s.replace(/(新卒)?(採用|人事).*$/, '').replace(/(でございます|です)$/, '').trim();
  for (const src of [subject, fromName]) {
    const m = src.match(re);
    if (m) return trimRole(m[0]);
  }
  const name = fromName.replace(/新卒採用チーム|新卒採用担当|新卒採用|採用担当|採用チーム|人事部|採用事務局|事務局|採用/g, '').trim();
  if (name.length >= 2 && !name.includes('@')) return name;
  // テストセンターの予約完了（testcenter@arorua.net）：本文の下のほうの「(5)受検企業」の次の行に会社名（「日本航空 株式会社」）
  // 欄の名前は行の最初（「(5)受検企業」「受検企業：」）。文の中の「受験企業へ提供されます」は欄ではない（ピアソンVUEの予約の案内）
  const label = body.match(/(?:^|\n)[ \t　]*(?:[(（]?\d+[)）][ \t　]*)?(?:受検|受験)企業名?[ \t　]*(?:[:：][ \t　]*|\n[ \t　]*)([^\n]{2,60})/);
  if (label && label[1].trim().length >= 2) return label[1].trim();
  if (inDomains(senderKey(from), TEST_CENTERS)) return senderKey(from);
  const m = body.slice(0, 500).match(re);
  return m ? trimRole(m[0]) : senderKey(from);
}

/** メールがどの行の会社のものか（会社名・別名・ドメインで探す） */
function rowsForMail(rows, f) {
  const ck = companyKey(f.company);
  const label = domainLabel(f.sender);
  // アドレス全体の英字（cyberagent@snar.jp、xxx@freee.n-ats.hrmos.co の freee）と、件名の【】の中（【freee】）
  const words = String(f.addr || f.local || '').split(/[^a-z0-9]+/);
  const tags = [...String(f.subject || '').matchAll(/【([^】]+)】/g)].map(m => companyKey(m[1]));
  const inLocal = key => key.length >= 3 && words.some(w => w.startsWith(key));
  // 1. 差出人・件名の会社名、送信元のドメイン、別名で探す
  const byName = rows.filter(row => {
    const rk = companyKey(row.name);
    if (rk.length >= 2 && (rk === ck || (ck.length >= 2 && (ck.includes(rk) || rk.includes(ck))))) return true;
    // 英字の略称は送信元のドメインと比べる（Cyber ↔ cyberagent.co.jp、KPMG ↔ kpmg.com）
    if (label && /^[a-z0-9&.\-]{3,}$/.test(rk) && (label.startsWith(rk) || label === rk.replace(/[&.\-]/g, ''))) return true;
    // 採用管理システムから届くメールは、アドレスの@の前に会社名が入っていることが多い（cyberagent@snar.jp）
    if (/^[a-z0-9&.\-]{3,}$/.test(rk) && inLocal(rk.replace(/[&.\-]/g, ''))) return true;
    if (rk.length >= 2 && tags.includes(rk)) return true;
    return row.aliases.some(a => a === f.sender || a === f.addr || f.sender.endsWith('.' + a) || (a.length >= 2 && !a.includes('.') && ck.includes(companyKey(a))) ||
      (a.includes('.') && inLocal(a.split('.')[0])));
  });
  if (byName.length) return byName;
  // 2. 差出人がほかの会社（「株式会社〇〇」）なら、本文に名前が出てくるだけの行には結びつけない（合同説明会の案内など）
  if (/株式会社|有限会社|合同会社/.test(f.company)) return [];
  // 3. 日程調整ツールなどから届いたメールは、件名・本文の最初に出てくる会社名で探す
  return rows.filter(row => {
    const rk = companyKey(row.name);
    return (rk.length >= 2 && f.text.includes(rk)) || row.aliases.some(a => a.length >= 2 && !a.includes('.') && f.text.includes(companyKey(a)));
  });
}

// ===== メールを読む（表にある会社のメールだけ。一度読んだメールは保存して、次からは新しいメールだけ問い合わせる） =====

/** 表の会社から検索の言葉を作る（ドメインは from:、名前は "〇〇"） */
function searchTerms(rows) {
  const terms = new Set();
  // 選考が終わった会社も探す（インターンのあとの本選考など、同じ会社の新しい選考を候補に出すため）
  for (const row of rows) {
    const name = normalize(row.name).replace(/株式会社|有限会社|合同会社|"/g, '').trim();
    if (name.length >= 2) terms.add('"' + name + '"');
    for (const a of row.aliases) terms.add(a.includes('.') ? 'from:' + a : '"' + a.replace(/"/g, '') + '"');
  }
  return [...terms];
}

function readCache(ss) {
  let sheet = ss.getSheetByName(CONFIG.CACHE_SHEET);
  if (!sheet) {
    sheet = ss.insertSheet(CONFIG.CACHE_SHEET);
    sheet.getRange(1, 1, 1, 6).setValues([['id', '日時', '差出人', '件名', '本文', 'スレッド']]);
    sheet.hideSheet();
  }
  const map = new Map();
  for (const r of sheet.getDataRange().getValues().slice(1)) {
    if (r[0]) map.set(String(r[0]), { id: String(r[0]), date: new Date(Number(r[1])), from: String(r[2]), subject: String(r[3]), body: String(r[4]), thread: String(r[5]) });
  }
  return { sheet, map, added: [] };
}

function writeCache(cache) {
  if (!cache.added.length) return;
  const safe = s => (/^[=+\-@]/.test(s) ? "'" + s : s);
  const row = d => [d.id, d.date.getTime(), safe(d.from), safe(d.subject), safe(d.body), d.thread];
  if (cache.map.size > CONFIG.CACHE_MAX) {
    const keep = [...cache.map.values()].sort((a, b) => b.date - a.date).slice(0, Math.floor(CONFIG.CACHE_MAX * 0.7));
    cache.sheet.clearContents();
    cache.sheet.getRange(1, 1, 1, 6).setValues([['id', '日時', '差出人', '件名', '本文', 'スレッド']]);
    cache.sheet.getRange(2, 1, keep.length, 6).setValues(keep.map(row));
  } else {
    cache.sheet.getRange(cache.sheet.getLastRow() + 1, 1, cache.added.length, 6).setValues(cache.added.map(row));
  }
  cache.added = [];
}

/**
 * 表の会社のメールをGmailから集める。
 * 前回の更新があれば、前回から後に届いたメールだけを問い合わせる（表に新しく足した会社は、DAYS日ぶん全部）。
 * 返り値は、保存済みのものも含めた直近 DAYS 日ぶんのメール
 */
function collectMails(ss, rows, full, now, blocked) {
  return runGmailSteps(collectSteps(ss, rows, full, now, blocked));
}

/**
 * collectSteps の Gmail への問い合わせに、GmailApp で答えながら最後まで進める（Apps Script 版）。
 * ブラウザ版（PWA）は、同じ collectSteps に Gmail API で答える（問い合わせが非同期なので、ここだけ別に書く）
 */
function runGmailSteps(steps) {
  let step = steps.next();
  while (!step.done) {
    const q = step.value;
    step = steps.next(q.search != null ? GmailApp.search(q.search, q.start, q.max) : GmailApp.getMessagesForThreads(q.threads));
  }
  return step.value;
}

/** 保存済みのメールのうち、直近 DAYS 日ぶん（読まない送信元を除く） */
function savedMails(cache, now, blocked) {
  const since = now.getTime() - CONFIG.DAYS * 864e5;
  return [...cache.map.values()].filter(d => d.date.getTime() >= since && !isBlocked(d.from, blocked));
}

/**
 * collectMails の中身。Gmail に問い合わせるところで止まり（yield）、答えをもらって続きを進める。
 *   yield { search, start, max } → スレッドの配列（getId・getLastMessageDate）
 *   yield { threads }            → スレッドごとのメールの配列（getId・getDate・getFrom・getSubject・getPlainBody）
 */
function* collectSteps(ss, rows, full, now, blocked) {
  const props = PropertiesService.getUserProperties();
  const lastRun = Number(props.getProperty('LAST_RUN') || 0);
  let known = [];
  try { known = JSON.parse(props.getProperty('TERMS') || '[]'); } catch (e) { known = []; }
  const terms = searchTerms(rows);
  const cache = readCache(ss);
  const incremental = !full && lastRun > 0 && now.getTime() - lastRun < CONFIG.DAYS * 864e5;
  const recentDays = incremental ? Math.ceil((now.getTime() - lastRun) / 864e5) + 1 : CONFIG.DAYS;
  const oldTerms = incremental ? terms.filter(t => known.includes(t)) : [];
  const newTerms = incremental ? terms.filter(t => !known.includes(t)) : terms;
  const seen = new Set();
  // Apps Script は1回6分で止まる。読むのに時間がかかったら途中でやめて、読んだぶんを保存する（続きは次の更新で読む）
  const started = Date.now();
  let stopped = false;
  const timeUp = () => (stopped = stopped || Date.now() - started > CONFIG.READ_LIMIT_SEC * 1000);
  // スレッドごとの、保存済みのいちばん新しいメールの日時（これより新しいメールがないスレッドは開かない）
  const savedLast = new Map();
  for (const d of cache.map.values()) savedLast.set(d.thread, Math.max(savedLast.get(d.thread) || 0, d.date.getTime()));
  /** 1回の検索で見つかったスレッドのうち、新しいメールがあるものだけ読み、保存する。返り値は見つかったスレッドの数 */
  const fetch = function* (q, start, max) {
    if (timeUp()) return 0;
    const found = yield { search: q, start, max };
    const threads = found.filter(t => {
      const id = t.getId();
      if (seen.has(id)) return false;
      seen.add(id);
      return !savedLast.has(id) || t.getLastMessageDate().getTime() > savedLast.get(id);
    });
    if (!threads.length) return found.length;
    const messages = yield { threads };
    for (let j = 0; j < threads.length && !timeUp(); j++) {
      for (const msg of messages[j]) {
        const id = msg.getId();
        if (cache.map.has(id)) continue;
        const d = { id, date: msg.getDate(), from: msg.getFrom(), subject: normalize(msg.getSubject()),
          body: normalize(msg.getPlainBody()).slice(0, CONFIG.CACHE_BODY_CHARS), thread: threads[j].getId() };
        cache.map.set(id, d);
        cache.added.push(d);
      }
    }
    return found.length;
  };
  // 就活サイト（会社名が出てくる宣伝が多い）からのメールは、検索の段階で除く（読む量が減って速くなる）
  const noMedia = ' ' + JOB_MEDIA.concat((blocked || []).filter(b => b.includes('.'))).map(d => '-from:' + d).join(' ');
  const search = function* (list, days) {
    for (let i = 0; i < list.length; i += CONFIG.TERMS_PER_QUERY) {
      yield* fetch('newer_than:' + days + 'd (' + list.slice(i, i + CONFIG.TERMS_PER_QUERY).join(' OR ') + ')' + noMedia, 0, CONFIG.THREADS_PER_QUERY);
    }
  };
  yield* search(oldTerms, recentDays);
  yield* search(newTerms, CONFIG.DAYS);
  // 表にない会社の選考メール（新しい会社の候補を出すため）。件名に選考の言葉があるメールを、就活サイトを除いて探す。
  // 数が多いので、100スレッドずつ CANDIDATE_MAX_THREADS まで読む
  const candidateDays = Math.min(incremental && props.getProperty('CANDIDATE_SEARCHED_V3') ? recentDays : CONFIG.CANDIDATE_DAYS, CONFIG.DAYS);
  const cq = 'newer_than:' + candidateDays + 'd (' + CONFIG.CANDIDATE_WORDS.map(w => 'subject:' + w).join(' OR ') + ')' + noMedia;
  for (let start = 0; start < CONFIG.CANDIDATE_MAX_THREADS; start += 100) {
    if ((yield* fetch(cq, start, 100)) < 100) break;
  }
  writeCache(cache);
  // 途中でやめたときは「読み終わった」しるしを付けない（次の更新で、同じ範囲の残りを読む。読んだメールは保存済みなので速い）
  if (!stopped) {
    props.setProperty('CANDIDATE_SEARCHED_V3', '1'); // 締切の言葉を足したので、V3（最初の1回は CANDIDATE_DAYS 日ぶん探す）
    props.setProperty('TERMS', JSON.stringify(terms));
  }
  return {
    stopped,
    // 前に保存した就活サイトのメールも読まない
    mails: savedMails(cache, now, blocked),
    info: stopped ? 'メールが多いので途中まで読みました（続きは次の更新で）' : incremental ?'前回から後のメールだけ問い合わせ（新しく足した会社' + newTerms.length + '件は' + CONFIG.DAYS + '日ぶん）' : CONFIG.DAYS + '日ぶん全部読み直し',
  };
}

// ===== メールを読み取る（日時と、何の日時か） =====

// 例: 2026年10月25日(土) 23:59 / 10/25(土)12:00 / 10月25日 12時
const DATE_RE = /(?<![\d\/])(?:(\d{4})\s*[年\/]\s*)?(\d{1,2})\s*[月\/]\s*(\d{1,2})(?!\d)\s*日?(?:\s*\(?\s*[月火水木金土日](?:曜日?)?\s*\)?)?(?:\s*(\d{1,2})\s*[:時]\s*(\d{2})?\s*分?)?/g;
const BEFORE_WORDS = /締切|〆切|締め切り|〆|期限|必着|受付終了|提出日/;
const AFTER_WORDS = /^[\s\d:時分()月火水木金土日曜正午頃]*(まで|迄|必着|締切|〆切|締め切り|〆)/;
const RANGE_START = /^\s*[~〜\-–ー]/;
// 終わりの時刻（「〜15:00」「～ 2026/11/01 15:00」）と、「〜」のすぐ後ろの日付（範囲の終わり）
const RANGE_END = /^\s*[~〜\-–ー]\s*(?:(?:\d{4}\s*[年\/]\s*)?\d{1,2}\s*[月\/]\s*\d{1,2}\s*日?\s*(?:\(\s*[月火水木金土日](?:曜日?)?\s*\))?\s*)?(\d{1,2})\s*[:時]\s*(\d{2})?/;
const AFTER_RANGE = /[~〜\-–ー]\s*$/;
const PERIOD_WORDS = /(受付|応募|エントリー|提出|募集|申込|申し込み)(期間|期限)/;
// キャンセル・変更・辞退の期限や、会社側がやることの日付（「結果は11/10までにご連絡します」）は締切ではない
const IGNORE_WORDS = /キャンセル|変更|辞退|取消|取り消し/;
const COMPANY_ACTION = /^[\s()月火水木金土日曜頃ごろ]*まで(に|には)?\s*(ご連絡|ご案内|お知らせ|ご通知|通知|連絡|ご返信|返信|お送り|送付)\s*(いた|し|差し上げ|させ|予定|を)/;
const RESULT_WORDS = /結果|合否|通過者|ご連絡予定/;
const EVENT_WORDS = /日\s*時|日\s*程|開催|実施|開始|集合|予約日|面接日|面談日/;

// メールの種類を見分ける言葉
const CONFIRMED_SUBJECT = /受け?付け?ました|受付完了|予約が?完了|申し?込み?が?完了|予約が?確定|確定しました|登録完了|提出完了|受検完了|回答完了|完了のお知らせ|完了しました|【確定】|確定のお知らせ|予定が確定|日程が?確定|日程が?決定|日程.{0,4}ご連絡|予約内容|予約(の)?確認/;
const THANKS_SUBJECT = /(提出|受検|応募|エントリー|予約|申し?込み?|回答|登録|参加).{0,8}(ありがとうございま|御礼|お礼)/;
// 「下記のとおり日程を確定いたしました」：候補日を返したあとの確定の連絡（「候補日程をご返信いただき」とあっても確定として読む）
const CONFIRM_STRONG = /(日程|日時)を?(確定|決定)(いた)?(しました|させていただきました)|(下記|以下)の(とおり|通り|内容で)(日程|日時)?を?(確定|決定)/;
const BODY_CONFIRMED = /予約を承りました|ご予約(いただき|頂き)(まして)?[、,]?\s*(誠に)?ありがとう|予約が完了(しました|いたしました)|ご予約を受け付けました|お申し?込みを受け付けました|お申し?込み(いただき|頂き)(まして)?[、,]?\s*(誠に)?ありがとう|(日程|日時)を?(確定|決定)(いた)?(しました|させていただきました)|(下記|以下)の(とおり|通り|内容で)(日程|日時)?を?(確定|決定)/;
const INVITE_SUBJECT = /^\s*(招待|更新された招待|invitation|updated invitation)\s*[:：]/i;
const CANCEL_SUBJECT = /キャンセル|取消|取り消し|辞退/;
const BROADCAST_SUBJECT = /開催(決定|日程|が決定|のお知らせ|します)|追加開催|募集開始|受付開始|定員|残りわずか|満席/;
const SELECTION_SUBJECT = /選考|面接|面談|グループディスカッション|グルディス|グループ討議|\bgd\b|グループワーク|筆記試験/i;
const NOT_SELECTION = /開催|お知らせ|体験|講座|ガイダンス|対策|模擬|セミナー|説明会|イベント|募集|登壇|サミット|フェア|座談会|優遇|チャンス|特集|限定/;
const BOOKING_REQUEST = /ご予約(ください|下さい)|予約して(ください|下さい)|ご予約をお待ち|ご都合の(よい|良い|いい)|候補日|いずれか|お選び|選択して|日程調整のお願い|ご希望の日程|(お|ご)?申し?込みはこちら|エントリーはこちら|ご予約はこちら|予約はこちら|参加はこちら/;
// 「模擬面接」「GD対策講座」などは選考ではない
const PRACTICE_WORDS = /模擬(面接|gd|グループディスカッション|グルディス)|(面接|gd|グループディスカッション|グルディス|es|webテスト|spi)\s*(対策|練習|講座|体験|セミナー)/gi;
const INTERN_WORDS = /インターン|仕事体験|サマー|ウィンター|summer|winter|オープンカンパニー|ジョブ型|1day|ワンデー/i;
const HONSENKO_WORDS = /本選考|早期選考|新卒(採用)?選考|総合職[^。\n]{0,6}選考|\d{2}卒[^。\n]{0,10}選考/;

// 選考の結果のメール
// 通過（次の選考に進む）：これがあれば、お見送りとは読まない
const PASS_WORDS = /(選考|面接|審査|書類|ES|エントリーシート|GD|ディスカッション).{0,8}(を)?(通過|合格)(され|し|とし|とな|とさ|いた|のお知らせ|のご連絡)|次(回|の)(選考|面接|ステップ)に(ぜひ)?(お)?進ん|お進みいただきたく|お進みいただけ|ご案内させていただきたく/i;
// 通過の連絡だとはっきりわかる言葉（日時のない通過の連絡を読むときに使う）
const STRONG_PASS = /(選考|面接|審査|書類|ES|エントリーシート|GD|ディスカッション).{0,8}(を)?(通過|合格)(され|し|とし|とな|とさ|いた|のお知らせ|のご連絡)|次(回|の)(選考|面接|ステップ)に(ぜひ)?(お)?進ん|お進みいただきたく|選考の結果[^。\n]{0,20}次回[^。\n]{0,15}(ご案内|お進み)/i;
// お見送り（不合格）
const REJECT_WORDS = /ご希望に(は)?(沿|添)いかね|ご期待に(は)?(沿|添)いかね|貴意に(沿|添)いかね|見送らせていただ|お見送りさせていただ|お見送りとさせていただ|お見送りすることと|採用を見送|ご縁がなかった|今回は.{0,15}(見送|叶わ|至りませんで)|ご期待に(お)?応えすることができ/;
// 内定・内々定（内定者向けのイベントや、宣伝の「早期内定」は除く）
const OFFER_WORDS = /内々?定(の|を)?(ご連絡|通知|のお知らせ|をお知らせ|をお出し|を出させ|とさせ|させていただ|いたし|致し)|内々?定(が)?決定|採用内定(の)?(ご連絡|通知)/;
const OFFER_NOT = /内定者|内定直結|早期内定|内定まで|内定獲得|内定率/;
// インターンシップの参加が決まった（インターンの選考に通った）
const INTERN_JOIN = /(インターン|仕事体験|ジョブ|プログラム).{0,25}(ご)?参加(が|を)?(決定|確定|いただくことが決|いただけることにな)/;

/** 選考の結果のメールなら、新しい「状況」（NG／内定／インターン参加決定）。それ以外は空 */
function resultOf(subject, body) {
  const t = subject + '\n' + body.slice(0, 1500);
  if (!/結果|選考|応募|面接|合否|内々?定|インターン|ご縁/.test(t)) return '';
  if (REJECT_WORDS.test(t) && !PASS_WORDS.test(t)) return 'NG';
  if (OFFER_WORDS.test(t) && !OFFER_NOT.test(subject)) return '内定';
  if (INTERN_JOIN.test(t) && !BOOKING_REQUEST.test(t) && !BROADCAST_SUBJECT.test(subject)) return 'インターン参加決定';
  return '';
}

/** 日付の直前（同じ文の中の30文字まで）・直後（同じ文の中の20文字まで）・すぐ上の2行 */
function textBefore(t, start) {
  const before = t.slice(Math.max(0, start - 30), start);
  const cut = Math.max(before.lastIndexOf('\n'), before.lastIndexOf('。'));
  return cut >= 0 ? before.slice(cut + 1) : before;
}
function textAfter(t, end) {
  return t.slice(end, end + 20).split(/[\n。]/)[0];
}
function linesAbove(t, index, n) {
  const lineStart = t.lastIndexOf('\n', index - 1);
  if (lineStart < 0) return [];
  // 「-----」「*****」のような区切りの線は飛ばす
  return t.slice(Math.max(0, lineStart - 200), lineStart).split('\n').map(s => s.trim())
    .filter(s => s && !/^[-=*_~─━・\s]+$/.test(s)).slice(-(n || 2)).reverse();
}

/** 返信メールの引用部分（「>」で始まる行や「2026年10月28日(水) 16:11 〇〇 <…>:」から下）を除く */
function stripQuote(body) {
  const out = [];
  for (const line of String(body || '').split('\n')) {
    if (/^\s*>/.test(line)) continue;
    if (/^\s*(-{2,}\s*(Original Message|元のメッセージ|Forwarded message|転送されたメッセージ)|差出人\s*[:：]|From\s*:)/i.test(line)) break;
    if (/^\s*\d{4}年\s*\d{1,2}月\s*\d{1,2}日.*\d{1,2}:\d{2}.*<[^>\s]+@[^>\s]+>\s*[:：]?\s*$/.test(line)) break;
    if (/^\s*On .+wrote:\s*$/.test(line)) break;
    out.push(line);
  }
  return out.join('\n');
}

/** DATE_RE のマッチを日時にする。時刻がなければ 23:59。年がなければメールの日付から決める */
function toDate(m, t, baseDate) {
  const month = Number(m[2]);
  const day = Number(m[3]);
  if (month < 1 || month > 12 || day < 1 || day > 31) return null;
  const end = m.index + m[0].length;
  let hasTime = m[4] != null && Number(m[4]) <= 24;
  let hour = hasTime ? Number(m[4]) : 23;
  let minute = hasTime && m[5] != null ? Number(m[5]) : (hasTime ? 0 : 59);
  if (!hasTime && /^\s*正午/.test(t.slice(end))) { hasTime = true; hour = 12; minute = 0; }
  if (hour === 24) { hour = 23; minute = 59; }
  const year = m[1] ? Number(m[1]) : baseDate.getFullYear();
  const d = new Date(year, month - 1, day, hour, minute);
  if (d.getMonth() !== month - 1) return null;
  if (!m[1] && d.getTime() < baseDate.getTime() - 60 * 864e5) d.setFullYear(year + 1); // 12月のメールに「1/10締切」
  return { date: d, hasTime };
}

/** 締切の日付（「締切：〜」「〜まで」）を全部取り出す */
function findDeadlines(t, baseDate) {
  const out = [];
  for (const m of t.matchAll(DATE_RE)) {
    const end = m.index + m[0].length;
    const before = textBefore(t, m.index), after = textAfter(t, end);
    if (RANGE_START.test(after) || IGNORE_WORDS.test(before + after)) continue;
    if (COMPANY_ACTION.test(after) || RESULT_WORDS.test(before)) continue;
    // 「■エントリー受付期間 10/26(月)10:00 ~ 11/5(木)10:00」の終わりの日も締切
    const period = AFTER_RANGE.test(before) && PERIOD_WORDS.test(before + '\n' + linesAbove(t, m.index, 3).join('\n'));
    if (!BEFORE_WORDS.test(before) && !AFTER_WORDS.test(after) && !period) continue;
    const p = toDate(m, t, baseDate);
    if (p) out.push({ date: p.date, near: before + m[0] + after, above: linesAbove(t, m.index) });
  }
  return out;
}

/** 予定の日時（「日時：11/16 17:00〜17:30」など）を取り出す。needWords なら「日時」などの見出しがあるものだけ */
function findEvents(t, baseDate, needWords) {
  const out = [];
  for (const m of t.matchAll(DATE_RE)) {
    const end = m.index + m[0].length;
    const before = textBefore(t, m.index), after = textAfter(t, end);
    if (AFTER_RANGE.test(before) || (needWords && !EVENT_WORDS.test(before))) continue;
    if (BEFORE_WORDS.test(before) || AFTER_WORDS.test(after) || IGNORE_WORDS.test(before + after)) continue;
    const p = toDate(m, t, baseDate);
    if (!p || !p.hasTime) continue;
    let finish = new Date(p.date.getTime() + 60 * 60 * 1000);
    const r = t.slice(end, end + 40).split('\n')[0].match(RANGE_END);
    if (r) { const e = new Date(p.date); e.setHours(Number(r[1]), r[2] ? Number(r[2]) : 0); if (e > p.date) finish = e; }
    out.push({ start: p.date, end: finish, near: t.slice(Math.max(0, m.index - 40), end + 40), above: linesAbove(t, m.index, 3) });
  }
  return out;
}

// 「1次面接通過」「書類選考の結果」「ES選考を通過されました」：終わった段階なので、次の選考を読むときは除く
const PASSED_STAGE = /[^\s、。]{0,12}?(選考|面接|gd|テスト|es|シート)(を|の|は)?(通過|合格|結果)/g;

/** 文から選考の段階を読み取る（どれにも当たらなければ空） */
function stepOf(s) {
  const t = normalize(s).replace(PRACTICE_WORDS, '').toLowerCase().replace(PASSED_STAGE, '');
  if (/テストセンター|webテスト|web試験|適性検査|spi|玉手箱|tg-web|受検/.test(t)) return 'Webテスト';
  if (/動画選考|動画面接|録画面接|動画提出/.test(t)) return '動画選考';
  if (/ai面接/.test(t)) return 'AI面接';
  if (/グループディスカッション|グルディス|グループ討議|\bgd\b|グループワーク|選考会/.test(t)) return 'GD';
  if (/最終面接|最終選考/.test(t)) return '最終面接';
  const m = t.match(/([一二三四1-4])次(面接|選考)/);
  if (m) return nthInterview(m[1], m[2]);
  if (/面接|面談/.test(t)) return '面接';
  if (/エントリーシート|\bes\b|書類|履歴書|課題|作文|ポートフォリオ|シート/.test(t)) return 'ES';
  return '';
}

/** 締切の段階：日付と同じ行 → すぐ上の行 → 件名 の順に見る */
function deadlineStep(dl, subject) {
  const sub = stepOf(subject);
  for (const s of [dl.near, ...dl.above]) {
    const x = stepOf(s);
    // 本文が「面接」とだけ書いていて、件名に「1次面接」などがあれば件名の方
    if (x) return x === '面接' && /面接$/.test(sub) ? sub : x;
  }
  return sub;
}

/** 予定の段階：件名を先に見る（「1次面接 日程確定」）。なければ日時のまわり */
function eventStep(subject, near, above) {
  const s = stepOf(subject), n = stepOf(near);
  // 日時のすぐ上の見出し（「二次面接」→「日時：…」）があれば、件名より先に見る（件名に「一次面接の御礼／二次面接のご案内」とあるときなど）
  const a = (above || []).map(stepOf).find(x => x) || '';
  if (a && a !== '面接') return a;
  if (s === '面接' && /面接$/.test(n)) return n;
  return s || n;
}

/** 選考種別（インターン／本選考／不明） */
function selectionKind(subject, body) {
  if (INTERN_WORDS.test(subject)) return 'インターン';
  if (HONSENKO_WORDS.test(subject)) return '本選考';
  const t = body.slice(0, 800);
  if (INTERN_WORDS.test(t)) return 'インターン';
  if (HONSENKO_WORDS.test(t)) return '本選考';
  return UNKNOWN_KIND;
}
const kindGroup = v => (/インターン/.test(v) ? 'インターン' : /本選考/.test(v) ? '本選考' : UNKNOWN_KIND);

/** メールの差出人・会社名・選考種別など（どの行のメールかを決めるのに使う） */
function mailInfo(d) {
  const subject = d.subject, body = d.body;
  return {
    id: d.id, date: d.date, subject, sender: senderKey(d.from), kind: selectionKind(subject, body),
    addr: (String(d.from).match(/<([^>]+)>/) || [0, String(d.from)])[1].trim().toLowerCase(),
    local: ((String(d.from).match(/<([^>]+)>/) || [0, String(d.from)])[1].trim().toLowerCase().split('@')[0]),
    url: 'https://mail.google.com/mail/u/0/#all/' + d.thread,
    company: extractCompany(subject, d.from, body),
    text: companyKey((subject + ' ' + body.slice(0, 600)).replace(/https?:\/\/\S+|\S+@\S+/g, ' ')),
  };
}

/**
 * メール1通から「次の選考」と「日時・期限」を読み取る。読み取れなければ null。
 * type は 予定（日程が決まった）／締切（締切の案内）／提出済（提出・受検の確認）
 */
function readMail(d, now) {
  const subject = d.subject, body = stripQuote(d.body); // 返信メールの引用部分（前のメールの文）は読まない
  const base = mailInfo(d);
  const sender = base.sender;
  // 就活サイトからのメールは宣伝が多いので読まない。キャンセルの連絡も読まない
  if (inDomains(sender, JOB_MEDIA)) return null;
  // 予約のキャンセルを受け付けた連絡：決まっていた日程を消す（次の予約まで、同じ選考の日程は未定）
  if (/キャンセル|取消|取り消し/.test(subject) && !/辞退/.test(subject) && /受け?付け?ました|完了|承りました/.test(subject + body.slice(0, 300))) {
    return { ...base, type: '取消', step: '', reason: '予約のキャンセル' };
  }
  if (CANCEL_SUBJECT.test(subject)) return null;
  // 選考の結果（お見送り・内定・インターン参加決定）
  const result = resultOf(subject, body);
  if (result) return { ...base, type: '結果', step: '', state: result, reason: result === 'NG' ? 'お見送りの連絡' : result === '内定' ? '内定の連絡' : 'インターン参加決定の連絡' };
  // 「開催決定」「受付開始」などのお知らせは、日時があっても予定にしない（締切だけ読む）
  const broadcast = BROADCAST_SUBJECT.test(subject);
  const isInvite = INVITE_SUBJECT.test(subject);
  const confirmed = !broadcast && (isInvite || CONFIRMED_SUBJECT.test(subject) || THANKS_SUBJECT.test(subject) ||
    (BODY_CONFIRMED.test(body.slice(0, 400)) && !BOOKING_REQUEST.test(body)) || CONFIRM_STRONG.test(body.slice(0, 600)));

  // 1. 日程が決まった（予約完了・日程確定・カレンダーの招待）
  if (confirmed) {
    const events = isInvite ? findEvents(subject, d.date, false).slice(0, 1)
      : (findEvents(body, d.date, true).length ? findEvents(body, d.date, true) : findEvents(body, d.date, false).slice(0, 1));
    const head = body.slice(0, 400);
    for (const e of events) {
      // 面談・座談会・OB/OG訪問（選考ではない予定）は、次の選考とは別の予定として読む
      const meeting = meetingOf(subject + '\n' + e.near + '\n' + head);
      if (meeting) return { ...base, type: '面談', step: '', what: meeting, when: e.start, end: e.end, reason: meeting + 'の予約' };
      // 件名にも日時のまわりにも何の予定か書いていないとき（TimeRexなどの日程調整ツール）は、本文の最初から読む
      let step = eventStep(subject, e.near, e.above) || stepOf(head);
      // 「面接」としか読めないとき、本文の最初に「《〇〇 4次選考》のご予約ありがとうございます」があれば、その段階（サイバーエージェント）
      const booked = (step === '面接' || step === '選考') && head.match(/([一二三四1-4])次(選考|面接)[》】」』]?\s*の(ご)?予約/);
      if (booked) step = nthInterview(booked[1], booked[2]);
      if (step && step !== 'ES') return { ...base, type: '予定', slot: EVENT, step, when: e.start, reason: e.start > now ? '日程が決まった' : '日程が決まった（もう過ぎている）' };
    }
    // 日時がない確認メールは、自分で出すもの（ES・Webテスト・動画・AI面接）の提出・受検の確認として読む
    // 件名がエントリーの確認なら、本文の「適性検査を受検ください」（これからやること）は受検の確認ではない（PwC の「エントリー登録ありがとうございました」）
    const done = stepOf(subject) || (/エントリー|応募/.test(subject) ? '' : stepOf(body.slice(0, 300)));
    if (SUBMIT_STEPS.includes(done)) return { ...base, type: '提出済', step: done, reason: '提出・受検の確認' };
    // 「エントリー受付完了」：締切まとめの「エントリー」を出したことにする（マイページの登録・プレエントリーは除く）
    if (/エントリー|応募/.test(subject) && !/プレエントリー|マイページ|登録/.test(subject)) return { ...base, type: '提出済', step: '', entry: true, reason: 'エントリーの確認' };
    return null;
  }
  // 2. 会社から日時を指定された選考の案内（宣伝・募集・自分で日程を選ぶ案内は除く）
  if (!broadcast && SELECTION_SUBJECT.test(subject.replace(PRACTICE_WORDS, '')) &&
    !NOT_SELECTION.test(subject) && !BOOKING_REQUEST.test(body)) {
    for (const e of findEvents(body, d.date, true)) {
      const meeting = meetingOf(subject + '\n' + e.near);
      if (meeting) return { ...base, type: '面談', step: '', what: meeting, when: e.start, end: e.end, reason: meeting + 'の日時の案内' };
      const step = eventStep(subject, e.near, e.above);
      if (step && step !== 'ES') return { ...base, type: '予定', slot: EVENT, step, when: e.start, reason: e.start > now ? '日時を指定された選考の案内' : '日時を指定された選考の案内（もう過ぎている）' };
    }
  }
  // 面談・座談会・OB/OG訪問の案内（「1次面接前の面談のご案内」）は、選考の締切・通過・日程調整として読まない
  //  （件名の「1次面接」を拾って、1次面接の日程調整と読んでいた。日時が決まった面談は、上で「面談」の予定として読む）。
  //  予約の締切が書いてあれば「面談の予約」の締切（表にない会社は締切まとめ、表にある会社はタスク）
  const meeting = meetingOf(subject);
  if (meeting) {
    const dl = findDeadlines(subject + '\n' + body, d.date).filter(x => x.date > now).sort((a, b) => a.date - b.date)[0];
    return dl ? { ...base, type: '締切', step: '', meeting, what: meeting + 'の予約', when: dl.date, reason: meeting + 'の予約の締切' } : null;
  }
  // 3. 締切の案内（いくつかあれば、いちばん手前の段階。同じ段階ならいちばん近い締切）
  const deadlines = findDeadlines(subject + '\n' + body, d.date).filter(dl => dl.date > now);
  const steps = deadlines.map(dl => ({ step: deadlineStep(dl, subject), when: dl.date })).filter(x => x.step)
    .sort((a, b) => stepRank(a.step) - stepRank(b.step) || a.when - b.when);
  // 通過の連絡に書いてある締切（選考が進んでいる）か。表にない会社なら、締切まとめではなく「新しい会社の候補」に出す
  //  （本文の下の方の注意書き「選考通過し、予約確定後に…」は通過の連絡ではないので、最初の500文字だけ見る）
  const passed = STRONG_PASS.test(subject + '\n' + body.slice(0, 500));
  if (steps.length) {
    const s = steps[0];
    return { ...base, type: '締切', slot: DEADLINE, step: s.step, when: s.when, passed, reason: SUBMIT_STEPS.includes(s.step) ? '締切の案内' : '予約の締切の案内' };
  }
  // 段階が書いていない「本エントリー締切」：締切まとめの「エントリー」（表の行には書かない）
  const entry = deadlines.filter(dl => /エントリー|応募/.test(subject + '\n' + dl.near + '\n' + dl.above.join('\n'))).sort((a, b) => a.date - b.date);
  if (entry.length) return { ...base, type: '締切', slot: DEADLINE, step: '', entry: true, when: entry[0].date, passed, reason: 'エントリーの締切' };
  // 4. 通過の連絡で、日時・締切が書いていないもの（「一次面接は通過とし、次回は二次面接」）→ 次の選考だけ
  //    （「特別選考にご案内させていただきたく」のようなスカウトの宣伝は、通過の連絡とは読まない）
  if (STRONG_PASS.test(subject + '\n' + body.slice(0, 1500)) && !broadcast && !ENTRY_AD.test(subject) && !/スカウト|オファー|特別選考|選考免除|面接確約/.test(subject)) {
    const next = nextStepOf(subject + '\n' + body.slice(0, 800));
    // 「ご都合の良い日程をご返信ください」などがあれば、あなたが日程を返す番（日程調整）
    if (next) return { ...base, type: '通過', slot: ASK_SCHEDULE.test(body) ? ADJUST : '', step: next, reason: '通過の連絡（次は' + next + '）' };
  }
  // 5. 日時を決めるお願い（「面接日程調整のご依頼」「ご都合の良い日程をお知らせください」）で、締切が書いていないもの → 日程調整
  //    （件名に「締切」とある案内は、締切のリマインド。「お早めにご予約ください」があっても日程調整ではない）
  if (!broadcast && !ENTRY_AD.test(subject) && SELECTION_SUBJECT.test(subject) && !NOT_SELECTION.test(subject) && !/締切|〆切|締め切り/.test(subject) &&
    (ASK_SCHEDULE.test(body) || /日程(の)?(ご)?調整|日程確認|ご返信依頼/.test(subject))) {
    const step = stepOf(subject) || stepOf(body.slice(0, 500));
    if (step && step !== 'ES') return { ...base, type: '調整', slot: ADJUST, step, reason: '日程調整のお願い' };
  }
  return null;
}

/**
 * 選考ではない予定（面談・座談会・OB/OG訪問）なら、その名前。面接・GDなど選考の予定なら空。
 * 「1次面接前の面談」のように面接の前の面談も、面談として読む
 */
function meetingOf(text) {
  const t = normalize(text).replace(/[^\s、。]{0,8}面接前の?面談/g, '面談');
  if (!/面談|座談会|OB訪問|OG訪問/.test(t)) return '';
  if (/面接|グループディスカッション|\bgd\b|選考会/i.test(t.replace(/選考要素(は)?なし|選考に(は)?(関係|影響)(し|ござい)ません/g, ''))) return '';
  return /座談会/.test(t) ? '座談会' : /OB訪問|OG訪問/.test(t) ? 'OB・OG訪問' : '面談';
}

// 会社から日程を聞かれている（あなたが返信・予約する番）
const ASK_SCHEDULE = /ご都合の?(良|よ|い)い(日程|日時|候補)|候補(日|日程|日時)を|日程を.{0,8}(ご返信|ご連絡|お知らせ|ご教示)|日程調整(のお願い|のご依頼|をお願い)|ご予約(ください|下さい|をお願い)|予約して(ください|下さい)|ご回答(ください|をお願い)/;

/**
 * 通過の連絡に書いてある、次の選考。
 * 通過した段階（「一次面接は通過」）より後で、いちばん手前の面接（「選考フロー：二次面接 → 最終面接」なら二次面接）。
 * 面接が書いていなければ GD・Webテストなど
 */
function nextStepOf(text) {
  const t = normalize(text).replace(PRACTICE_WORDS, '').toLowerCase();
  // 「次回【4次選考:人事面接】にご案内」とはっきり書いてあれば、その段階（「3次選考へご参加いただき」の3次選考ではない）
  const explicit = t.match(/次回[^。\n]{0,6}?(?:([一二三四1-4])次(面接|選考)|最終(面接|選考))/);
  if (explicit) return explicit[1] ? nthInterview(explicit[1], explicit[2]) : '最終面接';
  const stagesIn = s => [...s.matchAll(/([一二三四1-4])次(面接|選考)|最終(面接|選考)/g)].map(m => (m[1] ? nthInterview(m[1], m[2]) : '最終面接'));
  const passed = [...t.matchAll(PASSED_STAGE)].flatMap(m => stagesIn(m[0]));
  const floor = Math.max(-1, ...passed.map(stepRank));
  const rest = t.replace(PASSED_STAGE, '');
  const later = stagesIn(rest).filter(s => stepRank(s) > floor).sort((a, b) => stepRank(a) - stepRank(b));
  return later.length ? later[0] : stepOf(rest);
}

// ===== 表に書く =====

const show = v => (v instanceof Date ? (v.getMonth() + 1) + '/' + v.getDate() + ' ' + v.getHours() + ':' + String(v.getMinutes()).padStart(2, '0') : String(v || ''));
const sameTime = (a, b) => (!a && !b) || (a instanceof Date && b instanceof Date && Math.abs(a - b) < 60000);

/**
 * 読み取った内容を、メールの日付の古い順に表へ当てはめる。
 * 書いてよいとき：
 *   - 次の選考・日時がまだ空
 *   - 前にツールが書いたまま、あなたが変えていない（より新しいメールの内容で書き直す）
 *   - 今の日時がもう過ぎている
 *   - 前のシートから移した値より先の段階
 * それ以外（あなたが手で書いた内容と違う、どの行かわからない）は「確認待ち」へ
 */
function applyFindings(ss, table, findings, now, unread, replies, appts) {
  const { sheet, cols, rows } = table;
  const review = readReview(ss);
  const trace = [];
  const note = (f, result, detail) => trace.push([f.date, f.company, f.subject, f.kind, result, detail]);
  let written = 0;
  const changed = new Set();
  const withMail = new Set(); // メールが1通でも見つかった行
  const candidates = []; // 表にない会社の選考メール
  const deadlines = [], submitted = []; // 表にない会社の、ES・エントリーなどの締切と、その提出の確認（締切まとめ）
  // 説明会・セミナーなどのエントリー（締切まとめには出さない）
  const EVENT_ENTRY = /説明会|セミナー|座談会|talk|live|フォーラム|ウェビナー|webinar|社員訪問|懇親会/i;

  // 読んだが、次の選考の日時・締切が見つからなかったメールも記録に残す（うまくいかないときに原因を探せるように）
  for (const u of unread || []) {
    const rs = rowsForMail(rows, u);
    rs.forEach(r => withMail.add(r));
    if (!rs.length) continue;
    note(u, '読み取れなかった', rs.map(rowKey).join(' / ') + (inDomains(u.sender, JOB_MEDIA) ? '：就活サイトからのメールなので読まない'
      : '：次の選考の日時・締切が見つからない（キャンセル・お知らせ・自分で日程を選ぶ予約の募集なども、ここに入ります）'));
  }

  // 自動で表に入れる会社（表にない会社で、選考が始まっているとはっきりわかるメール）。あなたが「表から外す」「無視」にした会社は入れない
  const autoAdded = [];
  // 入れない会社：「表から外す」にした会社（外した）はずっと。前の候補タブで「無視」にした会社は、無視したあとに選考が進んだメールが来たら入れる
  // （スカウトの宣伝を無視したあとに、本物の通過の連絡が来ることがあるため）。キー → 外した・無視した日時（ずっとなら Infinity）
  const ignored = new Map((ss.getSheetByName(CONFIG.CANDIDATE_SHEET) ? readCandidates(ss).list : []).filter(x => x.status === '外した' || x.status === '無視')
    .map(x => [x.key, x.status === '外した' ? Infinity : x.decidedAt || 0]));
  // 外した・無視は会社ごと：同じ会社のメール（会社名・ドメイン・アドレスの中の会社名・前の形の会社名のどれかが同じ）のどれかで決めていれば、全部
  const ignoredUntil = new Map(); // メール → その日時より前のメールなら入れない
  if (ignored.size) {
    const keysOf = f => candidateTokens(f).concat([candidateNameKey(f)]);
    const parent = new Map();
    const root = t => { while (parent.get(t) !== t) t = parent.get(t); return t; };
    findings.forEach(f => { const ks = keysOf(f); ks.forEach(k => { if (!parent.has(k)) parent.set(k, k); }); ks.slice(1).forEach(k => { const a = root(ks[0]), b = root(k); if (a !== b) parent.set(a, b); }); });
    const until = new Map();
    [...parent.keys()].filter(k => ignored.has(k)).forEach(k => { const r = root(k); until.set(r, Math.max(until.get(r) || 0, ignored.get(k))); });
    findings.forEach(f => { const r = root(keysOf(f)[0]); if (until.has(r)) ignoredUntil.set(f, until.get(r)); });
  }
  const isIgnored = f => ignoredUntil.has(f) && f.date.getTime() <= ignoredUntil.get(f);
  // 締切（面接の予約の締切・通過の連絡に書いてある次の締切など）も、これからのものなら入れる（候補で聞かずに、間違っていたら「表から外す」）
  const autoAddable = f => (['予定', '通過', '提出済', '調整'].includes(f.type) || (f.type === '締切' && f.when > now)) && !f.entry && !f.meeting &&
    (f.type !== '提出済' || SUBMIT_STEPS.includes(f.step)) && now - f.date < CONFIG.CANDIDATE_DAYS * 864e5 &&
    !ENTRY_AD.test(f.subject) && !/スカウト|オファー|特別選考|選考免除|面接確約/.test(f.subject);
  /** 表の一番下に、その会社の行を足す（状況は選考中。別名には、送信元と、アドレスの中の会社名 freee・accenture など） */
  const addCompanyRow = (f, listName) => {
    const name = listName || cleanCompanyName(shortName(f.company)) || f.sender;
    const extra = candidateTokens(f).filter(t => /^name:[a-z0-9-]{3,}$/.test(t)).map(t => t.slice(5)).filter(t => companyKey(t) !== companyKey(name));
    const alias = [...new Set([candidateAlias(f, name)].concat(extra).filter(Boolean))].join(', ');
    const width = Math.max(...Object.values(cols));
    const values = Array(width).fill('');
    const put = (k, v) => { if (cols[k]) values[cols[k] - 1] = v; };
    put('name', /^[=+\-@]/.test(name) ? "'" + name : name); put('kind', kindGroup(f.kind)); put('state', '選考中'); put('alias', alias);
    const r = sheet.getLastRow() + 1;
    sheet.getRange(r, 1, 1, width).setValues([values]);
    const row = { r, name, kind: kindGroup(f.kind), state: '選考中', step: '', when: null, slot: '', mail: '', owned: null, memo: '', alias,
      aliases: alias.split(/[,、\s]+/).map(s => s.trim().toLowerCase()).filter(s => s) };
    rows.push(row);
    return row;
  };

  // 選考が終わった日：覚えてある日（結果のメール・画面で状況を変えた日）か、今回読んだメールの中の結果（お見送りなど）の連絡の日
  const resultAt = new Map();
  findings.filter(f => f.type === '結果' && FINAL_STATES.includes(f.state))
    .forEach(f => rowsForMail(rows, f).forEach(r => resultAt.set(r, Math.max(resultAt.get(r) || 0, f.date.getTime()))));
  const endedAtOf = r => (r.owned && r.owned.endedAt) || resultAt.get(r) || 0;

  findings.slice().sort((a, b) => a.date - b.date).forEach(f => {
    let all = rowsForMail(rows, f);
    all.forEach(r => withMail.add(r));
    // 候補に出すのは、これからの日程・締切か、最近（2週間以内）の提出の確認だけ（もう過ぎた日程は出さない）
    const upcoming = f.type === '提出済' || f.type === '通過' || f.type === '調整' ? now - f.date < 14 * 864e5 : f.type !== '取消' && f.when > now;
    // 表にない会社か、表の行の選考がどれも終わった会社（NGの会社の新しい募集など）
    const outside = !all.length || all.every(r => FINAL_STATES.includes(r.state));
    // エントリーの締切・受付は、表の行には書かない（どの選考かわからないため）
    if (f.entry && !outside) {
      note(f, '動かさない', all.map(rowKey).join(' / ') + '：エントリーの締切・受付の連絡なので、表には書かない');
      return;
    }
    // 面談・座談会などの予約の締切：表の行には書かない。表にない会社なら締切まとめ（表にある会社はタスク：applyTasks）
    if (f.meeting) {
      if (outside) {
        deadlines.push(all.length ? { ...f, listName: all[0].name } : f);
        note(f, '締切まとめ', '「' + f.company + '」の' + f.what + 'の締切を、「締切まとめ」に出しました');
      } else {
        note(f, 'タスク', all.map(rowKey).join(' / ') + '：' + f.what + 'の締切を、タスクに出しました（次の選考は変えない）');
      }
      return;
    }
    if (outside && f.type === '提出済') submitted.push(f);
    // ES・エントリー・Webテストなどの締切 → 締切まとめ（通過の連絡に書いてある締切は、候補の方に出す）
    if (outside && (f.entry || (f.type === '締切' && SUBMIT_STEPS.includes(f.step) && !f.passed))) {
      if (f.type === '締切' && EVENT_ENTRY.test(f.subject) && !INTERN_WORDS.test(f.subject) && !/選考/.test(f.subject)) {
        note(f, '締切まとめ', '説明会・セミナーなどのエントリーなので、締切まとめには出さない');
      } else if (f.type === '締切') {
        deadlines.push(all.length ? { ...f, listName: all[0].name } : f);
        note(f, '締切まとめ', '「' + f.company + '」は' + (all.length ? '表の選考が終わっている' : '表にない') + 'ので、「締切まとめ」に出しました（' + (f.entry ? 'エントリー' : f.step) + '）');
      } else {
        note(f, '締切まとめ', '「' + f.company + '」のエントリーの受付の連絡。締切まとめの「エントリー」を出したことにします');
      }
      return;
    }
    // 会社がわからない、いろいろな会社が使うシステムのメールは、候補に出さない・表に入れない：
    //   会社名のかわりに送信元しかない（テストセンターなど）か、会社名がシステムの名前（TimeRex・eeasy事務局 など）
    const sharedBase = SHARED_DOMAINS.find(d => inDomains(f.sender, [d]) || String(f.addr || '').endsWith('.' + d) || String(f.addr || '').endsWith('@' + d));
    const noCompany = !!sharedBase && (f.company === f.sender || companyKey(f.company).includes(sharedBase.split('.')[0]));
    // 選考が始まっている会社（日程確定・通過・提出完了・日程調整）は、表に行を足して、そのままこのメールを書き込む
    if (!all.length && !noCompany && autoAddable(f)) {
      if (isIgnored(f)) {
        note(f, '表にない会社', '「' + f.company + '」は「非表示」にした会社なので、会社一覧に入れない（設定の「非表示にしたもの」で戻せます）');
        return;
      }
      all = [addCompanyRow(f)];
      autoAdded.push({ ...f, auto: true });
      note(f, '自動で表に追加', '「' + f.company + '」は選考が始まっている（' + f.reason + '）ので、表に「' + all[0].name + '」の行を足しました');
    }
    if (!all.length) {
      if (noCompany) {
        note(f, '表にない会社', '会社がわからない（' + f.sender + ' は、いろいろな会社が使うシステム）ので、候補には出さない');
      } else if (upcoming) {
        // スカウト・早期選考の宣伝など：表に入れない（自分から申し込んで選考が進めば、そのメールで自動で入る）
        note(f, '表にない会社', '「' + f.company + '」に当たる行がない。スカウト・宣伝などで、選考が始まったとはわからないので、表に入れない（略称の会社なら「別名・ドメイン」に ' + f.sender + ' を書くと結びつきます）');
      } else {
        note(f, '表にない会社', '「' + f.company + '」に当たる行がない（' + (f.type === '結果' ? '選考の結果のメールなので' : '日程・締切はもう過ぎているので') + '、候補には出さない）');
      }
      return;
    }
    let active = all.filter(r => !FINAL_STATES.includes(r.state));
    if (!active.length) {
      // 選考が終わった会社から、選考が終わった日より後に届いたはっきりした連絡（日程確定・通過など）→ 新しい選考の行を自動で足す
      // （夏インターンNGのあとの冬インターン、インターンのあとの本選考など）。終わった日より前のメールは、終わった選考のメールなので足さない。
      // 終わった日がわからない行（前に手でNGにした行）は、別の選考種別のときだけ足す
      const reopen = { ...f, reopenName: all[0].name, reopen: all.map(r => r.kind + '：' + r.state).join('、') };
      const ends = all.map(endedAtOf);
      const isNew = ends.every(e => e > 0) ? f.date.getTime() > Math.max(...ends)
        : f.kind !== UNKNOWN_KIND && !all.some(r => kindGroup(r.kind) === f.kind) && f.date.getTime() > Math.max(...ends);
      if (upcoming && isNew && autoAddable(f) &&!(ignored.has(candidateTokens(reopen)[0]) && f.date.getTime() <= ignored.get(candidateTokens(reopen)[0]))) {
        const row = addCompanyRow(f, all[0].name);
        autoAdded.push({ ...reopen, auto: true });
        note(f, '自動で表に追加', all.map(rowKey).join(' / ') + ' は選考が終わっている。新しい選考（' + f.kind + '）が始まったので、表に「' + row.name + '」の行を足しました');
        all = [row];
        active = [row];
      } else {
        note(f, '動かさない', all.map(rowKey).join(' / ') + ' はどれも選考が終わっている');
        return;
      }
    }
    let target = null;
    if (f.kind !== UNKNOWN_KIND) {
      const same = active.filter(r => kindGroup(r.kind) === f.kind);
      const unknown = active.filter(r => kindGroup(r.kind) === UNKNOWN_KIND);
      target = same.length === 1 ? same[0] : (!same.length && unknown.length === 1 ? unknown[0] : null);
    } else if (active.length === 1) {
      target = active[0];
    }
    let proposal = f.type === '提出済' ? { step: WAITING } : f.type === '結果' ? { state: f.state } : f.type === '通過' || f.type === '調整' ? { step: f.step, slot: f.slot } : { step: f.step, slot: f.slot, when: f.when };
    if (!target && f.type === '取消') { note(f, '書く内容なし', active.map(rowKey).join(' / ') + '：予約のキャンセルだが、どの行かわからない'); return; }
    if (!target) {
      addReview(review, f, active, proposal, f.reason + '（どの行か選んでください）');
      note(f, '確認待ち（どの行か）', active.map(rowKey).join(' / ') + ' が当てはまる。メールの選考種別は「' + f.kind + '」');
      return;
    }
    // 「面接」とだけ書いてあるメール（「面接当日リマインド」など）は、行の今の面接のことと考える
    if (f.type !== '提出済' && f.type !== '通過' && f.type !== '調整' && f.step === '面接') {
      const step = interviewFor(f, target);
      if (!step) { note(f, '書かない', rowKey(target) + '：もう終わった面接（' + show(f.when) + '）のメール'); return; }
      f = { ...f, step, generic: step === '面接' };
      proposal = { step: f.step, slot: f.slot, when: f.when };
    }

    // 選考の結果（お見送り・内定・インターン参加決定）：「状況」を書く
    if (f.type === '結果') {
      const o = target.owned || {};
      let doubt = '';
      if (o.at && f.date.getTime() < o.at) doubt = 'このメールより新しい選考の連絡が、もう入っている';
      if (f.state === 'インターン参加決定' && kindGroup(target.kind) === '本選考') doubt = '本選考の行に、インターン参加決定のメール';
      if (doubt) {
        addReview(review, f, [target], proposal, f.reason + '（' + doubt + '）');
        note(f, '確認待ち', rowKey(target) + '：状況「' + f.state + '」にしてよいか確認（' + doubt + '）');
        return;
      }
      target.state = f.state;
      // 選考が終わった日（endedAt）：このあとに届いた選考のメールは、新しい選考として行を足す
      target.owned = Object.assign({}, o, { state: f.state, at: f.date.getTime(), endedAt: FINAL_STATES.includes(f.state) ? f.date.getTime() : undefined });
      target.mail = f.url;
      changed.add(target);
      written++;
      note(f, '反映', rowKey(target) + '：状況を「' + f.state + '」に（' + f.reason + '）');
      return;
    }

    // 予約のキャンセル：ツールが書いた日程なら消す（次の選考はそのまま）
    if (f.type === '取消') {
      const o = target.owned;
      if (target.slot === EVENT && target.when && o && o.step === target.step && sameTime(o.when ? new Date(o.when) : null, target.when) && f.date.getTime() >= (o.at || 0)) {
        note(f, '反映', rowKey(target) + '：' + target.step + '（' + show(target.when) + '）の予約がキャンセルされたので、日時を消す');
        target.when = null;
        target.slot = '';
        target.owned = { step: target.step, slot: '', when: null, at: f.date.getTime() };
        target.mail = f.url;
        changed.add(target);
        written++;
      } else {
        note(f, '書く内容なし', rowKey(target) + '：予約のキャンセルだが、消す日程がない（または手で書いた日程）');
      }
      return;
    }

    // 通過の連絡（日時なし）：次の選考が今より先なら書く。日時・期限は空にする（予約や日程確定のメールで入る）
    // 日程調整のお願い（日時なし）：次の選考が同じで日時がまだなら「日程調整」に、今より先の段階なら次の選考ごと書く
    if (f.type === '通過' || f.type === '調整') {
      const o = target.owned || {};
      let step = f.step;
      if (step === '面接') { // 何次かわからない「面接」は、行の今の面接（結果待ちなら次の面接）
        if (/^([1-4]次(面接|選考)|最終面接)$/.test(target.step)) step = target.step;
        else if (target.step === WAITING && /^([1-4]次(面接|選考)|最終面接)$/.test(o.done || '')) step = NEXT_AFTER_PASS[o.done] || '面接';
      }
      const newer = !(o.at && f.date.getTime() < o.at);
      const ahead = progress(step, '') > rowRank(target);
      // 同じ段階で日時がまだの行に「日程調整」を付ける（前の版で次の選考だけ書いた行も）。
      // 返信済みの「確定待ち」は、そのあとに来た新しいお願いでだけ「日程調整」に戻す
      const sameNoDate = f.slot === ADJUST && target.step === step && !target.when && target.slot !== ADJUST &&
        (target.slot !== WAIT_CONFIRM || f.date.getTime() > (o.at || 0));
      // 同じ段階の呼び方だけ違う（ツールが前に「1次面接」と書いたが、メールは「1次選考」）→ メールの呼び方に直す
      const renamed = target.step !== step && rankKey(target.step) === rankKey(step) && o.step === target.step;
      if (newer && renamed && !ahead) {
        // 呼び方だけ直す（日時・締切/日程はそのまま）
        note(f, '反映', rowKey(target) + '：次の選考の呼び方を「' + target.step + '」から「' + step + '」に（' + f.reason + '）');
        target.step = step;
        target.owned = Object.assign({}, o, { step });
        target.mail = f.url;
        changed.add(target);
        written++;
        return;
      }
      // まだ受けていない選考（予定しているGDなど）より前に届いた「通過」は、その選考の結果ではない（書類選考の通過など）
      if (ahead && target.slot === EVENT && target.when && target.when.getTime() > f.date.getTime()) {
        note(f, '書かない', rowKey(target) + '：' + f.reason + 'だが、予定している「' + target.step + '」（' + show(target.when) + '）より前に届いたので、その結果ではない');
        return;
      }
      if (newer && (ahead || sameNoDate)) {
        target.step = step;
        target.slot = f.slot || '';
        target.when = null;
        if (!target.state) target.state = '選考中';
        target.owned = { step, slot: target.slot, when: null, at: f.date.getTime() };
        target.mail = f.url;
        changed.add(target);
        written++;
        note(f, '反映', rowKey(target) + '：次の選考を「' + step + '」' + (target.slot ? '・「' + target.slot + '」' : '') + 'に（' + f.reason + '）');
      } else {
        note(f, '書く内容なし', rowKey(target) + '：' + f.reason + 'だが、今の「' + (stepLabel(target.step, target.slot) || '空') + '」と同じか先の段階');
      }
      return;
    }

    // 提出・受検の確認：今の次の選考と同じ段階なら、次の選考を「結果待ち」にする（終わった段階は覚えておく）
    if (f.type === '提出済') {
      // 次の選考が同じ段階か、空か、もっと前の段階なら（表に足したばかりの会社など）
      const r = rowRank(target);
      if (target.step === f.step || !target.step || (target.step !== WAITING && r >= 0 && r < stepRank(f.step))) {
        target.step = WAITING;
        target.when = null;
        target.slot = '';
        target.owned = { step: WAITING, when: null, slot: '', done: f.step, at: f.date.getTime() };
        target.mail = f.url;
        changed.add(target);
        written++;
        note(f, '反映', rowKey(target) + '：次の選考を「結果待ち」に（' + f.step + 'の提出・受検の確認）');
      } else {
        note(f, '書く内容なし', rowKey(target) + '：' + f.step + 'の確認だが、次の選考は「' + (target.step || '空') + '」');
      }
      return;
    }

    const owned = target.owned;
    // mine：今の次の選考・日時はツールが書いたもの。edited：ツールが書いたあとに、あなたが書き直した
    const mine = !!owned && owned.step !== undefined;
    const edited = mine && (owned.step !== target.step || !sameTime(owned.when ? new Date(owned.when) : null, target.when) ||
      (owned.slot !== undefined && owned.slot !== target.slot));
    const label = stepLabel(f.step, f.slot);
    if (target.step === f.step && target.slot === f.slot && sameTime(target.when, f.when)) { note(f, '変更なし', rowKey(target) + '：もう同じ内容'); return; }
    const past = !target.when || target.when < now;
    const fRank = progress(f.step, f.slot);
    const ahead = fRank > rowRank(target);
    // 何次かわからない「面接」（4次面接のあとの面接など）は、前の段階とは考えない
    const behind = fRank < rowRank(target) && stepRank(f.step) >= 0 && !f.generic;
    // ただし、通過の連絡だけで（日時なしで）先に進めた行に、その連絡より後の日時の予定（GDなど）が見つかったら、
    // その通過は予定の選考の結果ではなかった（書類選考の通過など）ので、予定の方に戻す
    const o = owned || {};
    const undoPass = behind && mine && !edited && o.when == null && o.step && o.step !== WAITING &&
      f.slot === EVENT && f.when && f.when.getTime() > (o.at || 0);
    // 先に進んだ行に、前の段階の案内（日程が決まったあとの予約締切のリマインド、提出後のESの締切など）が来ても戻さない
    if (behind && !undoPass) {
      note(f, '書かない', rowKey(target) + '：今の「' + stepLabel(target.step, target.slot) + '」より前の段階（' + label + '）');
      return;
    }
    if (mine && !edited && !undoPass && f.date.getTime() < (owned.at || 0)) { note(f, '書かない', rowKey(target) + '：もっと新しいメールの内容が入っている'); return; }
    const empty = !target.step && !target.when;
    const ok = empty || (mine && !edited) || (!edited && (past || ahead));
    if (!ok && f.when < now) { note(f, '書かない', rowKey(target) + '：もう過ぎた日程（' + label + ' ' + show(f.when) + '）で、今の内容と違う'); return; }
    if (!ok) {
      addReview(review, f, [target], proposal, f.reason + (edited ? '（手で書いた内容と違う）' : '（今の内容と違う）'));
      note(f, '確認待ち', rowKey(target) + '：今は「' + (stepLabel(target.step, target.slot) || '空') + ' ' + show(target.when) + '」、メールは「' + label + ' ' + show(f.when) + '」');
      return;
    }
    target.step = f.step;
    target.slot = f.slot;
    target.when = f.when;
    if (!target.state) target.state = '選考中';
    target.owned = { step: f.step, slot: f.slot, when: f.when.getTime(), at: f.date.getTime() };
    target.mail = f.url;
    changed.add(target);
    written++;
    note(f, '反映', rowKey(target) + '：次の選考「' + label + '」、日時・期限「' + show(f.when) + '」（' + f.reason + '）');
  });

  // 次の選考が決まっているのに日時が空の行は、空のままにしない：まず「日程調整」（下で返信が見つかれば「確定待ち」）
  for (const row of rows) {
    if (FINAL_STATES.includes(row.state) || !row.step || row.step === WAITING || row.when) continue;
    if (row.slot === ADJUST || row.slot === WAIT_CONFIRM) continue;
    trace.push([now, row.name, '（日時が空）', row.kind, '反映', rowKey(row) + '：次の選考「' + row.step + '」の日時がまだなので「日程調整」に']);
    row.slot = ADJUST;
    if (row.owned && row.owned.step !== undefined) row.owned = Object.assign({}, row.owned, { slot: ADJUST });
    changed.add(row);
    written++;
  }

  // 日程調整の行：そのメールのやりとり（スレッド）に、あとからあなたが返信していれば「確定待ち」にする
  for (const row of rows) {
    if (row.slot !== ADJUST || row.when || FINAL_STATES.includes(row.state)) continue;
    const thread = (String(row.mail).match(/#all\/([A-Za-z0-9]+)/) || [])[1];
    const replied = thread && replies && replies.get(thread);
    const since = (row.owned && row.owned.at) || 0;
    if (!replied || replied <= since) continue;
    trace.push([new Date(replied), row.name, '（あなたの返信）', row.kind, '反映', rowKey(row) + '：日程調整のメールに返信したので「確定待ち」に']);
    row.slot = WAIT_CONFIRM;
    row.owned = Object.assign({}, row.owned || {}, { step: row.step, slot: WAIT_CONFIRM, when: null });
    changed.add(row);
    written++;
  }

  // 面接・GDなどの日程が過ぎた行は「結果待ち」にする（受けた段階は覚えておく）
  for (const row of rows) {
    if (FINAL_STATES.includes(row.state) || row.slot !== EVENT || !row.when || row.step === WAITING) continue;
    if (row.when.getTime() + CONFIG.EVENT_HOURS * 3600e3 > now.getTime()) continue;
    trace.push([row.when, row.name, '（日程が過ぎた）', row.kind, '反映', rowKey(row) + '：' + row.step + '（' + show(row.when) + '）が終わったので「結果待ち」に']);
    row.owned = { step: WAITING, when: null, slot: '', done: row.step, at: row.when.getTime() };
    row.step = WAITING;
    row.when = null;
    row.slot = '';
    changed.add(row);
    written++;
  }

  // メールが1通も見つからなかった行（会社名がメールと違う、メールが古すぎる、など）
  for (const row of rows) {
    if (FINAL_STATES.includes(row.state) || withMail.has(row)) continue;
    trace.push([now, row.name, '（メールが見つからない）', row.kind, 'メールなし', 'Gmailで ' + searchTerms([row]).join(' / ') +
      ' を検索したが、直近' + CONFIG.DAYS + '日にこの行のメールがない。会社名がメールと違うときは「別名・ドメイン」に送信元のドメイン（例：cyberagent.co.jp）を書いてください']);
  }

  // 変わったセルだけ書く（行の中のほかのセルは触らない）
  for (const row of changed) {
    sheet.getRange(row.r, cols.state).setValue(row.state);
    sheet.getRange(row.r, cols.step).setValue(row.step);
    if (cols.slot) sheet.getRange(row.r, cols.slot).setValue(row.slot || '');
    sheet.getRange(row.r, cols.when).setValue(row.when || '');
    sheet.getRange(row.r, cols.owned).setValue(row.owned ? JSON.stringify(row.owned) : '');
    sheet.getRange(row.r, cols.mail).setValue(row.mail);
  }
  writeReview(review);
  writeTrace(ss, trace);
  // エントリーの募集（「エントリー受付開始」「〜のご案内」のESの締切）は、受けている選考ではないので候補にしない
  // 自動で表に入れた会社も、候補タブに「表に入れました」として出す（間違っていたら「表から外す」）
  const newCompanies = writeCandidates(ss, candidates.filter(f => f.type !== '取消' &&
    !(f.type === '締切' && SUBMIT_STEPS.includes(f.step) && ENTRY_AD.test(f.subject))).concat(autoAdded), now);
  // 面談などの予約が終わった連絡（日時が決まった面談）も渡す：締切まとめの「面談の予約」を予約済みにする
  const newDeadlines = writeDeadlines(ss, deadlines, submitted.concat(appts || []), now);
  return { written, pending: review.list.filter(x => x.status === '未確認').length, candidates: newCompanies, deadlines: newDeadlines };
}

// ----- やること（選考とは別の、頼まれごと：履歴書の提出など） -----

// 頼まれる書類など（ES・Webテスト・課題などは「次の選考」として扱うので、ここには入れない）
const TASK_ITEMS = ['履歴書', '職務経歴書', '成績証明書', '卒業見込証明書', '卒業見込み証明書', '健康診断書', '健康診断証明書', '顔写真', '証明写真', 'ポートフォリオ', 'アンケート', '同意書', '誓約書', '学生証',
  '適性検査', 'Webテスト', 'WEBテスト', 'SPI', 'テストセンター', '玉手箱'];
// 適性検査などは、ふだんは「次の選考」（Webテスト）。面接の前に受けるよう頼まれたときだけ、やることにする
const TEST_ITEMS = ['適性検査', 'Webテスト', 'WEBテスト', 'SPI', 'テストセンター', '玉手箱'];
const TASK_ITEM_RE = TASK_ITEMS.join('|');
// 「履歴書のご準備をお願いいたします」「履歴書データをご送付いただければ」「アンケートにご回答ください」
const TASK_RE = new RegExp('(' + TASK_ITEM_RE + ')[^。\\n]{0,30}?(ご提出|ご送付|ご送信|ご返送|ご準備|ご用意|ご回答|ご記入|アップロード|お送り|ご持参|お持ち|ご受検|ご受験|受検|受験)(を)?(して)?(の上|お願|いただ|頂|くだ|下さ|ください)', 'g');
// 受け取りの連絡（「履歴書を受領いたしました」「履歴書のご提出ありがとうございました」）
const RECEIPT_RE = new RegExp('(' + TASK_ITEM_RE + ')[^。\\n]{0,15}?(受領|拝受|受け付け|受付|確認いたしました|確認しました|ご提出(いただき)?ありがとう|お送りいただきありがとう)', 'g');
const taskName = item => (item === '証明写真' ? '顔写真' : item) + (item === 'アンケート' ? 'の回答' : TEST_ITEMS.includes(item) ? 'の受検' : 'の提出');

/**
 * メール1通から、頼まれごと（履歴書の提出など）と期限を取り出す。
 *   期限：日付が書いてあればその日。「面接前日までに」なら面接の前日、「面接までに」なら面接の日時（表の日時から計算する）
 */
function tasksOf(d) {
  const subject = d.subject, body = stripQuote(d.body);
  if (BROADCAST_SUBJECT.test(subject) || ENTRY_AD.test(subject) || THANKS_SUBJECT.test(subject) || CANCEL_SUBJECT.test(subject)) return [];
  const t = normalize(subject + '\n' + body);
  const out = [];
  for (const m of t.matchAll(TASK_RE)) {
    // いちばん動詞に近い書類の名前（「顔写真付きの履歴書データをご送付」なら履歴書）
    const items = [...m[0].matchAll(new RegExp(TASK_ITEM_RE, 'g'))].map(x => x[0]);
    const item = items[items.length - 1];
    if (out.some(x => x.item === item)) continue;
    const near = t.slice(Math.max(0, m.index - 100), m.index + m[0].length + 120);
    let due = null, rel = '', days = 0;
    const eve = near.match(/面接(日)?の?(前日|前々日)/);
    // 「面接終了後」「面接を終えられましたら」：面接のあとにやること（面接の日が期限。面接が始まるまでは一覧に出さない）
    if (/面接(の)?(終了|終わ|を終え|の後|後に|後、|後は)|終了後|を終えられ|を終えた(ら|あと|後)/.test(near)) rel = 'after';
    else if (eve) { rel = 'eve'; days = eve[2] === '前々日' ? 2 : 1; }
    else if (/面接(日|当日)?(まで|迄)|面接(の)?(前|開始前)まで|面接(時|当日)に?(ご持参|お持ち)|面接(の)?際に/.test(near)) rel = 'until';
    else {
      const dl = findDeadlines(near, d.date).filter(x => x.date > d.date).sort((a, b) => a.date - b.date)[0];
      if (dl) due = dl.date;
    }
    // 適性検査などは、面接の前に受けるよう頼まれたときだけ（ふだんは「次の選考：Webテスト」として読む）
    if (TEST_ITEMS.includes(item) && !rel && !/面接(の)?(前|までに|まで)/.test(near)) continue;
    if (TEST_ITEMS.includes(item) && !rel && !due) rel = 'until'; // 受検期限が書いていなければ面接まで
    const name = TEST_ITEMS.includes(name0(item)) ? '適性検査' : name0(item);
    out.push({ ...mailInfo(d), item: name, what: taskName(name), due, rel, days, thread: d.thread,
      detail: taskHowto(name, near) });
  }
  return out;
}

const name0 = item => (item === '証明写真' ? '顔写真' : item);

/**
 * 頼まれごとを一言で（「マイページで顔写真を登録（未提出なら）」「メールに添付して履歴書を提出」）。
 * text はもとのメールの、頼まれている文のまわり
 */
function taskHowto(item, text) {
  const t = normalize(text);
  if (/ご持参|お持ち/.test(t)) return '当日、' + item + 'を持参';
  const where = /マイページ|Entry ?Box|Step ?Navi/i.test(t) ? 'マイページで'
    : /本メール|ご返信|返信いただ|メールにて|メールで|添付/.test(t) ? 'メールに添付して'
    : /アップロード/.test(t) ? 'アップロードして'
    : /https?:\/\/|URL|フォーム|リンク/.test(t) ? 'フォームで' : '';
  const verb = item === 'アンケート' ? 'に回答' : item === '適性検査' ? 'を受検' : /登録/.test(t) ? 'を登録' : 'を提出';
  const cond = /未提出の方(のみ)?|提出済み?の方.{0,20}(不要|ご放念)/.test(t) ? '（未提出なら）' : '';
  return where + item + verb + cond;
}

/** 受け取りの連絡（「履歴書を受領いたしました」）から、受け取られた書類の名前 */
function receiptsOf(d) {
  const t = normalize(d.subject + '\n' + stripQuote(d.body).slice(0, 1500));
  const items = [...new Set([...t.matchAll(RECEIPT_RE)].map(m => m[1]))];
  return items.map(item => ({ ...mailInfo(d), item }));
}

// 「くわしく」は前の版のシートに後から足したので、いちばん右
const TASK_HEADER = ['キー', '企業名', 'タスク', '期限', '済', 'メール', '（ツール用）', 'くわしく'];
const taskKey = (row, item, thread) => rowKey(row) + '|' + item + '|' + thread;

/** タスクのシート（前の版の「やること」シートがあれば、名前を変えて使う）。なければ null */
function taskSheet(ss) {
  const old = !ss.getSheetByName(CONFIG.TASK_SHEET) && ss.getSheetByName('やること');
  if (old) old.setName(CONFIG.TASK_SHEET);
  return ss.getSheetByName(CONFIG.TASK_SHEET);
}

function readTasks(ss) {
  let sheet = taskSheet(ss);
  if (!sheet) {
    sheet = ss.insertSheet(CONFIG.TASK_SHEET);
    sheet.getRange(1, 1, 1, TASK_HEADER.length).setValues([TASK_HEADER]).setFontWeight('bold');
    sheet.setFrozenRows(1);
    sheet.hideColumns(1, 1);
    sheet.hideColumns(TASK_HEADER.indexOf('（ツール用）') + 1, 1);
    sheet.setColumnWidth(3, 200);
  }
  const list = sheet.getDataRange().getValues().slice(1).filter(r => r[0]).map(r => {
    let tool = {};
    try { tool = r[6] ? JSON.parse(r[6]) : {}; } catch (e) { tool = {}; }
    return { key: String(r[0]), name: String(r[1]), what: String(r[2]), due: r[3] instanceof Date ? r[3] : null, done: r[4] === true || String(r[4]).toUpperCase() === 'TRUE', mail: String(r[5]), tool, detail: String(r[7] || '') };
  });
  return { sheet, list };
}

function writeTasks(sheet, list) {
  const safe = v => (typeof v === 'string' && /^[=+\-@]/.test(v) ? "'" + v : v);
  const rows = list.map(x => [x.key, safe(x.name), safe(x.what), x.due || '', x.done, x.mail, JSON.stringify(x.tool), safe(x.detail || '')]);
  sheet.getRange(1, 1, 1, TASK_HEADER.length).setValues([TASK_HEADER]).setFontWeight('bold'); // 前の版のシートにも「くわしく」の見出しを付ける
  sheet.setColumnWidth(TASK_HEADER.length, 420);
  sheet.getRange(2, 1, Math.max(1, sheet.getLastRow() - 1), TASK_HEADER.length).clearContent();
  if (rows.length) {
    sheet.getRange(2, 1, rows.length, TASK_HEADER.length).setValues(rows);
    sheet.getRange(2, 5, rows.length, 1).insertCheckboxes();
    sheet.getRange(2, 4, rows.length, 1).setNumberFormat('yyyy/m/d(ddd) hh:mm');
  }
}

/**
 * 「やること」シートを更新する。
 *   - 新しい頼まれごとを足す（同じメールの同じ書類は1回だけ）
 *   - 「面接まで」「面接の前日まで」の期限は、表のその会社の面接の日時から計算し直す（あなたが期限を書き直していたら触らない）
 *   - 受け取りの連絡が来たか、そのメールにあなたが書類の名前や「添付」を書いて返信していたら「済」にする
 */
function applyTasks(ss, table, found, receipts, myMails, now) {
  const { sheet, list } = readTasks(ss);
  const byKey = new Map(list.map(x => [x.key, x]));
  let detailAdded = false;
  const rowByKey = new Map(table.rows.map(r => [rowKey(r), r]));
  const trace = [];
  // どの行の頼まれごとか（行がいくつかあってわからないものは足さない）
  const targetOf = f => {
    const active = rowsForMail(table.rows, f).filter(r => !FINAL_STATES.includes(r.state));
    if (f.kind !== UNKNOWN_KIND) {
      const same = active.filter(r => kindGroup(r.kind) === f.kind);
      if (same.length === 1) return same[0];
      if (same.length) return null;
    }
    return active.length === 1 ? active[0] : null;
  };
  for (const f of found.slice().sort((a, b) => a.date - b.date)) {
    const row = targetOf(f);
    if (!row) continue;
    // 面談・座談会などの予定：会社ごとに1つ（日程を変えたら、新しいメールの日時にする）
    if (f.appt) {
      const key = rowKey(row) + '|予定|' + f.what;
      const old = byKey.get(key);
      if (old && (old.tool.at || 0) >= f.date.getTime()) continue;
      const x = old || { key, name: row.name, done: false };
      Object.assign(x, { what: f.what, due: f.when, mail: f.url, done: false,
        tool: { appt: true, end: f.end ? f.end.getTime() : null, at: f.date.getTime(), thread: f.thread, row: rowKey(row), due: f.when.getTime() } });
      if (!old) { list.push(x); byKey.set(key, x); }
      continue;
    }
    const key = taskKey(row, f.item, f.thread);
    if (byKey.has(key)) {
      // 前の版で入れたもの：期限の決め方（面接の前日・面接まで・面接のあと）を読み直す
      const ex = byKey.get(key), t = ex.tool || {};
      if (!ex.done && !t.manual && (t.rel || '') !== (f.rel || '')) { t.rel = f.rel; t.days = f.days; ex.tool = t; }
      if (f.detail && ex.detail !== f.detail) { ex.detail = f.detail; detailAdded = true; } // 前の版で入れたもの（長い文）も一言に置きかえる
      continue;
    }
    const x = { key, name: row.name, what: f.what, due: f.due, done: false, mail: f.url, detail: f.detail || '',
      tool: { rel: f.rel, days: f.days, at: f.date.getTime(), thread: f.thread, item: f.item, row: rowKey(row), due: f.due ? f.due.getTime() : null } };
    list.push(x);
    byKey.set(key, x);
  }
  let changed = 0;
  for (const x of list) {
    if (x.done) continue;
    const t = x.tool || {};
    // 予定（面談など）は、終わったら自動で済
    if (t.appt) {
      if ((t.end || (x.due ? x.due.getTime() : 0)) < now.getTime()) { x.done = true; changed++; }
      continue;
    }
    // 面談などの予約（「面談の予約」）：その会社の面談などの日時が、頼まれたあとに決まったら済
    if (/の予約$/.test(t.item || '') && list.some(y => y.tool && y.tool.appt && y.tool.row === t.row && (y.tool.at || 0) >= (t.at || 0))) {
      x.done = true; t.autoDone = '予約した'; changed++; continue;
    }
    // 受け取りの連絡（書類の名前が同じで、頼まれたあとに届いたもの）
    const received = receipts.some(r => r.item === t.item && r.date.getTime() >= (t.at || 0) && rowsForMail(table.rows, r).some(rr => rowKey(rr) === t.row));
    // あなたの返信（同じスレッドで、書類の名前か「添付」が書いてあるもの）
    const sent = myMails.some(d => d.thread === t.thread && d.date.getTime() > (t.at || 0) && (d.body.includes(t.item) || /添付/.test(d.body)));
    if (received || sent) { x.done = true; t.autoDone = received ? '受け取りの連絡' : 'あなたの返信'; changed++; continue; }
    // 「面接まで」「面接の前日まで」：表の日時（面接の日程）から計算し直す。あなたが期限を書き直していたら触らない
    if (t.rel) {
      const editedDue = t.due ? !(x.due && Math.abs(x.due.getTime() - t.due) < 60000) : !!x.due;
      if (editedDue) continue;
      const row = rowByKey.get(t.row);
      let due = null;
      let showFrom = null;
      if (row && row.slot === EVENT && row.when) {
        due = new Date(row.when);
        if (t.rel === 'eve') { due.setDate(due.getDate() - (t.days || 1)); due.setHours(23, 59, 0, 0); }
        if (t.rel === 'after') { showFrom = row.when.getTime(); due.setHours(23, 59, 0, 0); } // 面接の日のうちに
      }
      if (!sameTime(due, x.due) || (t.rel === 'after' && t.showFrom !== showFrom)) { x.due = due; t.due = due ? due.getTime() : null; t.showFrom = showFrom; changed++; }
    }
  }
  if (changed || detailAdded || list.length !== byKey.size || found.length) writeTasks(sheet, list);
  return list.filter(x => !x.done).length;
}

/** 画面のカレンダーから、やることを自分で足す（会社は空でもよい）。dueIso はその日の日時 */
function addTask(name, what, dueIso) {
  what = String(what || '').trim();
  if (!what) throw new Error('タスクの内容を書いてください');
  const ss = getSpreadsheet();
  const { sheet, list } = readTasks(ss);
  const due = dueIso ? new Date(dueIso) : null;
  list.push({ key: 'manual|' + Date.now(), name: String(name || '').trim(), what, due, done: false, mail: '',
    tool: { manual: true, due: due ? due.getTime() : null } });
  writeTasks(sheet, list);
  return getData();
}

/** 画面の「済」ボタン */
function doneTask(key) {
  const ss = getSpreadsheet();
  const { sheet, list } = readTasks(ss);
  const x = list.find(t => t.key === key);
  if (x) { x.done = true; writeTasks(sheet, list); }
  return getData();
}

// ----- 新しい会社の候補 -----

const ENTRY_AD = /受付開始|受付中|募集|エントリー.{0,8}ご案内|開催|イベント/;
const CANDIDATE_HEADER = ['key', '会社名', '選考種別', '送信元', '件名', '次の選考', '日時・期限', 'メール', '状態', '件数', '別名・ドメイン', '表にある行', '決めた日時'];

/** 表に足すときの会社名（「株式会社」などを除く） */
const shortName = s => normalize(s).replace(/株式会社|有限会社|合同会社|\(株\)/g, '').trim();

/**
 * 候補の会社を見分ける手がかり（どれか1つでも同じメールは、同じ会社としてまとめる）。
 *   - 会社名（部署の名前は除く）
 *   - 会社自身のドメイン（freee.co.jp）と、その名前の部分（freee）
 *   - 採用システムから届いたメールの、アドレスの中の会社（accenture@mail.axol.jp の accenture、〜@freee.n-ats.hrmos.co の freee）
 * 表にある会社の新しい選考は、表の会社名1つ
 */
function candidateTokens(f) {
  if (f.reopen) return [companyKey(f.reopenName) + '|新しい選考'];
  const out = [];
  const nameKey = companyKey(cleanCompanyName(shortName(f.company)));
  if (nameKey.length >= 2 && !nameKey.includes('.') && !nameKey.includes('@')) {
    out.push('name:' + nameKey);
    // 「JALグループ」は「JAL」とも（jal@mail.axol.jp・日本航空の jal_j@ と結びつける）
    const noGroup = nameKey.replace(/グループ$/, '');
    if (noGroup !== nameKey && noGroup.length >= 2) out.push('name:' + noGroup);
  }
  const shared = inDomains(f.sender, SHARED_DOMAINS);
  if (f.sender && !f.sender.includes('@') && !shared) {
    out.push('domain:' + f.sender);
    const label = domainLabel(f.sender);
    if (label) out.push('name:' + label);
  }
  if (shared && f.addr) {
    const [local, host] = f.addr.split('@');
    const base = SHARED_DOMAINS.find(d => host === d || host.endsWith('.' + d)) || '';
    const sub = host.slice(0, Math.max(0, host.length - base.length - 1)).split('.')[0]; // freee.n-ats.hrmos.co → freee
    const generic = /^(mail|info|no-?reply|noreply_tc|support|notice|notification|system|admin|contact|recruit|saiyo|jinji|candidate|n-ats|www|testcenter)$/;
    if (sub && !generic.test(sub) && /^[a-z][a-z0-9-]{2,}$/.test(sub)) out.push('name:' + sub);
    // jal_j@mail.axol.jp の jal（_ や . のあとは部署などの印）
    const head = (local || '').split(/[_.+]/)[0];
    if (head && !generic.test(head) && /^[a-z][a-z0-9-]{2,}$/.test(head)) out.push('name:' + head);
  }
  return out.length ? out : [f.sender];
}

/** 差出人の名前から、部署の名前を除いた会社名（「アクセンチュア 同志社大学リクルーターチーム」→「アクセンチュア」） */
function cleanCompanyName(name) {
  let s = normalize(String(name || '')).trim();
  const head = s.split(/\s+/)[0];
  if (head !== s && /リクルーター|チーム|採用|人事|事務局|担当|センター|オフィス/.test(s.slice(head.length))) s = head;
  s = s.replace(/[(（][^)）]*[)）]\s*$/, '').replace(/(人事本部|人事部|人事|新卒採用|採用担当|採用チーム|採用|リクルーター.*|事務局)$/, '').trim();
  return s.length >= 2 ? s : String(name || '').trim();
}

/** 会社名で見分けるキー（前の形。前に「無視」「追加」を決めた候補を引き継ぐため） */
function candidateNameKey(f) {
  const k = companyKey(shortName(f.company));
  return k && !k.includes('.') && !k.includes('@') ? k : f.sender;
}

/** 表に足すときの「別名・ドメイン」：会社のドメイン。採用管理システムから届くときはアドレス */
function candidateAlias(f, name) {
  // 会社名だけで結びつくなら書かない（グループ会社でドメインが同じこともあるため）
  if (rowsForMail([{ name, aliases: [] }], f).length) return '';
  if (!f.sender.includes('@') && !inDomains(f.sender, SHARED_DOMAINS)) return f.sender;
  // 日程調整ツールなどの共通のアドレス（info@eeasy.jp など）は、ほかの会社のメールにも当たるので書かない
  const local = f.addr.split('@')[0];
  if (/^(info|no-?reply|support|notice|notification|system|mail|admin|contact|recruit)$/.test(local)) return '';
  return f.addr && !FREE_MAIL.test(f.addr.split('@')[1] || '') ? f.addr : '';
}

function readCandidates(ss) {
  const sheet = sheetWithHeader(ss, CONFIG.CANDIDATE_SHEET, CANDIDATE_HEADER);
  const list = sheet.getDataRange().getValues().slice(1).filter(r => r[0]).map(r => ({
    key: String(r[0]), name: String(r[1]), kind: String(r[2]), sender: String(r[3]), subject: String(r[4]), label: String(r[5]),
    when: r[6] instanceof Date ? r[6] : null, url: String(r[7]), status: String(r[8] || '未確認'), count: Number(r[9] || 1), alias: String(r[10] || ''), reopen: String(r[11] || ''),
    decidedAt: r[12] instanceof Date ? r[12].getTime() : Number(r[12] || 0),
  }));
  return { sheet, list };
}

/**
 * 「新しい会社の候補」シートを作り直す。会社ごとに1行（いちばん新しいメールの内容）。
 * 「追加」「無視」を選んだ会社は、その状態のまま残す（無視した会社は、もう出さない）
 */
function writeCandidates(ss, found, now) {
  const { sheet, list } = readCandidates(ss);
  const decided = new Map(list.filter(x => x.status !== '未確認').map(x => [x.key, x]));
  const groups = new Map();
  // 選考が進んだしるし（日程確定・通過・提出の確認）。無視した会社でも、無視したあとにこれが来たら、もう一度出す
  const progressed = f => f.type === '予定' || f.type === '通過' || f.type === '提出済';
  // 同じ会社のメールをまとめる：会社名・ドメイン・アドレスの中の会社（candidateTokens）が1つでも同じなら同じ会社（つながりをたどる）
  const sorted = found.slice().sort((a, b) => b.date - a.date);
  const tokens = sorted.map(candidateTokens);
  const parent = new Map();
  const root = t => { while (parent.get(t) !== t) { parent.set(t, parent.get(parent.get(t))); t = parent.get(t); } return t; };
  tokens.forEach(ts => ts.forEach(t => { if (!parent.has(t)) parent.set(t, t); }));
  tokens.forEach(ts => ts.slice(1).forEach(t => { const a = root(ts[0]), b = root(t); if (a !== b) parent.set(a, b); }));
  const companies = new Map(); // つながりの元 → その会社のメール（新しい順）
  sorted.forEach((f, i) => { const r = root(tokens[i][0]); if (!companies.has(r)) companies.set(r, []); companies.get(r).push({ f, ts: tokens[i] }); });
  const adopted = new Set(); // 前のキー（会社名・ドメインなど）で決めてあったもの：今の候補に引き継いだので、別の行には残さない
  for (const ms of companies.values()) {
    const all = [...new Set(ms.flatMap(m => m.ts))].sort();
    const key = all[0];
    const f = ms[0].f; // いちばん新しいメール
    // 名前：部署の名前を除いた会社名のうち、いちばん多いもの（同じ数なら短いほう）。表にある会社の新しい選考は、表と同じ会社名
    const counts = new Map();
    ms.forEach(m => { const n = m.f.reopenName || cleanCompanyName(shortName(m.f.company)); if (n && !/[@.]/.test(n)) counts.set(n, (counts.get(n) || 0) + 1); });
    const name = [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].length - b[0].length).map(e => e[0])[0] || f.sender;
    // 前に「無視」「追加」を決めてあれば引き継ぐ（前の形のキー：会社名・ドメインでも探す）
    const d = all.map(t => decided.get(t)).find(Boolean) || ms.map(m => decided.get(candidateNameKey(m.f)) || decided.get('domain:' + m.f.sender)).find(Boolean);
    if (d && d.key !== key) adopted.add(d.key);
    const kindKnown = ms.map(m => m.f.kind).find(k => kindGroup(k) !== UNKNOWN_KIND);
    groups.set(key, {
      key, name, kind: kindKnown || f.kind, sender: f.sender, subject: f.subject,
      label: f.type === '提出済' ? f.step + 'の提出・受検' : stepLabel(f.step, f.slot), when: f.when || null, url: f.url,
      // 自動で表に入れた会社は「自動で追加」（入れた日時も覚える：候補タブに2週間出す）
      // 「戻した」会社・前の候補タブで「無視」にした会社は、また自動で入れたら「自動で追加」にする（「自動」の印と「表から外す」を出すため）
      status: d && !(['戻した', '無視'].includes(d.status) && ms.some(m => m.f.auto)) ? d.status : ms.some(m => m.f.auto) ? '自動で追加' : '未確認',
      decidedAt: d && !(['戻した', '無視'].includes(d.status) && ms.some(m => m.f.auto)) ? d.decidedAt : ms.some(m => m.f.auto) ? (now || new Date()).getTime() : 0,
      count: ms.length, alias: f.reopen ? '' : candidateAlias(f, name), reopen: f.reopen || '',
      lastProgress: Math.max(0, ...ms.filter(m => progressed(m.f)).map(m => m.f.date.getTime())),
    });
  }
  for (const g of groups.values()) {
    if (g.status === '無視' && g.lastProgress > (g.decidedAt || 0)) { g.status = '未確認'; g.decidedAt = 0; }
  }
  for (const [key, x] of decided) if (!groups.has(key) && !adopted.has(key)) groups.set(key, x);
  const safe = v => (typeof v === 'string' && /^[=+\-@]/.test(v) ? "'" + v : v);
  const rows = [...groups.values()].map(x => [x.key, safe(x.name), x.kind, x.sender, safe(x.subject), x.label, x.when || '', x.url, x.status, x.count, safe(x.alias), x.reopen || '',
    x.decidedAt ? new Date(x.decidedAt) : '']);
  sheet.getRange(1, 1, 1, CANDIDATE_HEADER.length).setValues([CANDIDATE_HEADER]); // 前の形（列が少ない）のシートでも見出しをそろえる
  sheet.getRange(2, 1, Math.max(1, sheet.getLastRow() - 1), CANDIDATE_HEADER.length).clearContent();
  if (rows.length) sheet.getRange(2, 1, rows.length, CANDIDATE_HEADER.length).setValues(rows);
  return [...groups.values()].filter(x => x.status === '未確認').length;
}

/** 画面の「新しい会社の候補」：追加（表に行を足して、すぐメールから更新）か無視 */
function resolveCandidate(key, add) {
  const ss = getSpreadsheet();
  const { sheet, list } = readCandidates(ss);
  const i = list.findIndex(x => x.key === key);
  if (i < 0) return getData();
  const x = list[i];
  sheet.getRange(i + 2, CANDIDATE_HEADER.indexOf('状態') + 1).setValue(add ? '追加' : '無視');
  sheet.getRange(i + 2, CANDIDATE_HEADER.indexOf('決めた日時') + 1).setValue(new Date());
  if (add) addTableRow(ss, x.name, x.kind, x.alias);
  return getData();
}

// ----- 日程未定タブの「非表示」：その会社のその選考を、日程未定に出さない（次の選考が変わったら、また出す）。「戻す」で出す -----
// 隠した行は 会社名｜選考種別 → { step（隠したときの次の選考）, at（隠した日時） }。ユーザーの設定に入れる（ブラウザ版はデータと一緒に保存）

function readHiddenUndecided() {
  try { return JSON.parse(PropertiesService.getUserProperties().getProperty('HIDDEN_UNDECIDED') || '{}') || {}; } catch (e) { return {}; }
}

function hideUndecided(key, step) {
  const h = readHiddenUndecided();
  h[key] = { step: String(step || ''), at: new Date().getTime() };
  PropertiesService.getUserProperties().setProperty('HIDDEN_UNDECIDED', JSON.stringify(h));
  return getData();
}

function unhideUndecided(key) {
  const h = readHiddenUndecided();
  delete h[key];
  PropertiesService.getUserProperties().setProperty('HIDDEN_UNDECIDED', JSON.stringify(h));
  return getData();
}

/** 画面の「表から外す」：自動で表に入れた会社を、表から消す。その会社は、もう自動で入れない（候補のシートは「外した」にする。設定の「表から外した会社」で戻せる） */
function removeAutoAdded(key) {
  const ss = getSpreadsheet();
  const { sheet, list } = readCandidates(ss);
  const i = list.findIndex(x => x.key === key);
  if (i < 0) return getData();
  const x = list[i];
  sheet.getRange(i + 2, CANDIDATE_HEADER.indexOf('状態') + 1).setValue('外した');
  sheet.getRange(i + 2, CANDIDATE_HEADER.indexOf('決めた日時') + 1).setValue(new Date());
  // その会社の行を消す（下の行から消す：行の番号がずれないように）。選考が終わった会社に足した新しい選考なら、足した行（終わっていない行）だけ
  const table = readTable(ss);
  table.rows.filter(r => companyKey(r.name) === companyKey(x.name) && !(x.reopen && FINAL_STATES.includes(r.state)))
    .sort((a, b) => b.r - a.r).forEach(r => table.sheet.deleteRow(r.r));
  if (!x.reopen) deleteHistory(ss, x.name); // 関係ない会社だったので、カレンダーの記録も消す
  return getData();
}

/** 設定の「表から外した会社」の「戻す」：また自動で表に入れるようにして、読み込み済みのメールから表を作り直す */
function restoreRemoved(key) {
  const ss = getSpreadsheet();
  const { sheet, list } = readCandidates(ss);
  const i = list.findIndex(x => x.key === key);
  if (i < 0) return getData();
  sheet.getRange(i + 2, CANDIDATE_HEADER.indexOf('状態') + 1).setValue('戻した');
  sheet.getRange(i + 2, CANDIDATE_HEADER.indexOf('決めた日時') + 1).setValue(new Date());
  try { update(false); } catch (e) { Logger.log('戻したあとの更新でエラー: ' + e.message); }
  return getData();
}

/**
 * 表の一番下に会社の行を足し、すぐメールから更新して次の選考と日時を入れる（候補の「表に追加」・締切まとめの「提出済み」）。
 * waitFor があれば、その結果待ちの行にする（締切まとめで「ESを出した」→ ESの結果待ち）
 */
function addTableRow(ss, name, kind, alias, waitFor) {
  const values = { name, kind: kindGroup(kind), alias };
  if (waitFor) Object.assign(values, { step: WAITING, owned: JSON.stringify({ step: WAITING, when: null, slot: '', done: waitFor, at: new Date().getTime() }) });
  appendTableRow(ss, values);
}

/** 表の一番下に行を足し（状況は選考中）、すぐメールから更新する。values は { 列のキー: 値 } */
function appendTableRow(ss, values) {
  const table = readTable(ss);
  const width = Math.max(...Object.values(table.cols));
  const row = Array(width).fill('');
  const put = (k, v) => { if (table.cols[k] && v != null) row[table.cols[k] - 1] = v; };
  put('state', '選考中');
  for (const k in values) put(k, values[k]);
  table.sheet.getRange(table.sheet.getLastRow() + 1, 1, 1, width).setValues([row]);
  // 足した会社のメールを読んで、次の選考と日時を入れる（Gmailの回数の上限に達していたら、次の更新で入る）
  try { update(false); } catch (e) { Logger.log('表に追加したあとの更新でエラー: ' + e.message); }
}

/**
 * 画面で入れた会社の行の中身を、表に書ける形にそろえる。x = { name, kind, state, step, slot, when（ISOの文字）, memo, alias }
 *   - 次の選考がない・結果待ちなら、締切/日程は空。結果待ちなら日時も空
 */
function companyFields(x) {
  x = x || {};
  const name = String(x.name || '').trim();
  if (!name) throw new Error('会社名を書いてください');
  const kind = KIND_LIST.includes(x.kind) ? x.kind : UNKNOWN_KIND;
  const state = STATE_LIST.includes(x.state) ? x.state : '選考中';
  const step = STEP_LIST.includes(x.step) ? x.step : '';
  const when = x.when ? new Date(x.when) : null;
  if (when && isNaN(when.getTime())) throw new Error('日時の形がおかしいです');
  const slot = step && step !== WAITING ? (SLOT_LIST.includes(x.slot) ? x.slot : defaultSlot(step)) : '';
  const safe = v => (/^[=+\-@]/.test(v) ? "'" + v : v); // 「=」で始まる文字を式にしない
  return { name: safe(name), kind, state, step, slot, when: step === WAITING ? '' : when || '',
    memo: safe(String(x.memo || '').trim()), alias: safe(String(x.alias || '').trim()) };
}

/** 同じ会社・選考種別の、選考中の行がほかにあればエラー（except は今直している行） */
function checkDuplicate(table, f, except) {
  const name = String(f.name).replace(/^'/, '');
  if (table.rows.some(r => r !== except && companyKey(r.name) === companyKey(name) && r.kind === f.kind && !FINAL_STATES.includes(r.state) && !FINAL_STATES.includes(f.state))) {
    throw new Error(name + '（' + f.kind + '）はもう表にあります');
  }
}

/**
 * 画面の「会社を追加」：マイページでしか見られない会社などを、表に足す（手で書いた行と同じ扱い。ツールは書き換えず、違うメールは確認待ち）。
 * x = { name, kind, step, slot, when（ISOの文字）, memo, alias }
 */
function addCompany(x) {
  const f = companyFields(Object.assign({}, x, { state: '選考中' }));
  const ss = getSpreadsheet();
  checkDuplicate(readTable(ss), f, null);
  appendTableRow(ss, f);
  return getData();
}

/** 表の行を key（会社名｜選考種別）で探す。なければエラー */
function findRow(table, key) {
  const row = table.rows.find(r => rowKey(r) === key);
  if (!row) throw new Error('その会社の行が見つかりません（ほかの端末で変わったかもしれません。画面を開き直してください）');
  return row;
}

/**
 * 画面の「編集」：会社の行の中身を直す（スプレッドシートで手で直したのと同じ扱い。ツールは書き換えず、違うメールは確認待ち）。
 * x = { name, kind, state, step, slot, when, memo, alias }
 */
function updateCompany(key, x) {
  const ss = getSpreadsheet();
  const table = readTable(ss);
  const row = findRow(table, key);
  const f = companyFields(x);
  checkDuplicate(table, f, row);
  for (const k of ['name', 'kind', 'state', 'step', 'slot', 'when', 'memo', 'alias']) {
    if (table.cols[k]) table.sheet.getRange(row.r, table.cols[k]).setValue(f[k]);
  }
  // 状況を NG・内定などに変えたら、その日を選考が終わった日として覚える（このあとに届いた選考のメールは、新しい選考として行を足す）
  const wasEnded = FINAL_STATES.includes(row.state), ended = FINAL_STATES.includes(f.state);
  if (table.cols.owned && wasEnded !== ended) {
    const owned = Object.assign({}, row.owned || {}, { endedAt: ended ? new Date().getTime() : undefined });
    table.sheet.getRange(row.r, table.cols.owned).setValue(JSON.stringify(owned));
  }
  return getData();
}

/** 画面の「削除」：会社の行を消す */
function deleteCompany(key) {
  const ss = getSpreadsheet();
  const table = readTable(ss);
  table.sheet.deleteRow(findRow(table, key).r);
  return getData();
}

// ----- 画面から「読まない送信元」を直す -----

/** 読まない送信元の一覧（画面用）：[{ sender, on（読まない）, memo, fixed（最初からある就活サイト。消せない） }] */
function blockList(ss) {
  const sheet = ss.getSheetByName(CONFIG.BLOCK_SHEET);
  const fixed = new Set(DEFAULT_MEDIA.map(m => m[0]));
  if (!sheet) return DEFAULT_MEDIA.map(([d, name]) => ({ sender: d, on: true, memo: name, fixed: true }));
  return sheet.getDataRange().getValues().slice(1).filter(r => blockKey(r[0]).length >= 2)
    .map(r => ({ sender: blockKey(r[0]), on: !(r[1] === false || String(r[1]).toUpperCase() === 'FALSE'), memo: String(r[2] || ''), fixed: fixed.has(blockKey(r[0])) }));
}

/** 「読まない送信元」シートの、その送信元の行（2行目から数えた行番号）。なければ 0 */
function blockRow(sheet, sender) {
  const i = sheet.getDataRange().getValues().findIndex((r, n) => n > 0 && blockKey(r[0]) === blockKey(sender));
  return i > 0 ? i + 1 : 0;
}

/** チェックの付け外し（on：読まない） */
function setBlocked(sender, on) {
  const ss = getSpreadsheet();
  readBlocked(ss); // シートがなければ作り、就活サイトを入れておく
  const sheet = ss.getSheetByName(CONFIG.BLOCK_SHEET);
  const r = blockRow(sheet, sender);
  if (!r) throw new Error('その送信元は一覧にありません');
  sheet.getRange(r, 2).setValue(!!on);
  return getData();
}

/** 読まない送信元を足す（ドメイン・アドレス・差出人の名前） */
function addBlocked(sender, memo) {
  const key = blockKey(sender || '');
  if (key.length < 2) throw new Error('ドメイン・アドレス・差出人の名前のどれかを、2文字以上で書いてください');
  const ss = getSpreadsheet();
  readBlocked(ss);
  const sheet = ss.getSheetByName(CONFIG.BLOCK_SHEET);
  if (blockRow(sheet, key)) throw new Error(key + ' はもうあります');
  const safe = v => (/^[=+\-@]/.test(v) ? "'" + v : v);
  const r = sheet.getLastRow() + 1;
  sheet.getRange(r, 1, 1, 3).setValues([[safe(key), true, safe(String(memo || '').trim())]]);
  sheet.getRange(r, 2).insertCheckboxes();
  return getData();
}

/** 自分で足した読まない送信元を消す（最初からある就活サイトは、消しても次の更新で戻るので消せない） */
function removeBlocked(sender) {
  if (DEFAULT_MEDIA.some(m => m[0] === blockKey(sender))) throw new Error('最初からある就活サイトは消せません。読みたいときはチェックを外してください');
  const ss = getSpreadsheet();
  const sheet = ss.getSheetByName(CONFIG.BLOCK_SHEET);
  const r = sheet ? blockRow(sheet, sender) : 0;
  if (!r) throw new Error('その送信元は一覧にありません');
  sheet.deleteRow(r);
  return getData();
}

// ----- 書き出し・読み込み（データを手元に持ち出す・別の端末や版に移す） -----

// 書き出さないシート：読み込み済みメール（大きい。読み込んだあと Gmail から読み直す）・更新の記録・ブラウザ版の設定
const EXPORT_SKIP = () => [CONFIG.CACHE_SHEET, CONFIG.TRACE_SHEET, '（ツール用）設定'];

/** 全部のシートを、1つの文字（JSON）にする。日時は { $date: ミリ秒 } */
function exportAll() {
  const ss = getSpreadsheet();
  const sheets = ss.getSheets().filter(s => !EXPORT_SKIP().includes(s.getName())).map(s => ({
    name: s.getName(),
    rows: s.getLastRow() ? s.getDataRange().getValues().map(r => r.map(v => (v instanceof Date ? { $date: v.getTime() } : v))) : [],
  }));
  return JSON.stringify({ app: 'shukatsu-calendar', version: 1, exportedAt: new Date().toISOString(), sheets });
}

/** exportAll で書き出したものを読み込む（同じ名前のシートは中身を入れかえる）。次の更新で、メールを60日ぶん読み直す */
function importAll(text) {
  let d = null;
  try { d = JSON.parse(text); } catch (e) { d = null; }
  if (!d || d.app !== 'shukatsu-calendar' || !Array.isArray(d.sheets)) throw new Error('このアプリのファイルではありません（「書き出す」で作ったファイルを選んでください）');
  if (!d.sheets.some(s => s.name === CONFIG.SHEET_NAME)) throw new Error('ファイルに「' + CONFIG.SHEET_NAME + '」が入っていません');
  const ss = getSpreadsheet();
  for (const s of d.sheets) {
    if (EXPORT_SKIP().includes(s.name)) continue;
    const sheet = ss.getSheetByName(s.name) || ss.insertSheet(s.name);
    sheet.clearContents();
    const rows = (s.rows || []).map(r => r.map(v => (v && typeof v === 'object' && '$date' in v ? new Date(v.$date) : v)));
    const width = Math.max(0, ...rows.map(r => r.length));
    if (rows.length && width) sheet.getRange(1, 1, rows.length, width).setValues(rows.map(r => r.concat(Array(width - r.length).fill(''))));
  }
  // 読み込み済みメールは入っていないので、前回の更新の日時を消して、次の更新で60日ぶん読み直す
  const props = PropertiesService.getUserProperties();
  props.setProperty('LAST_RUN', '');
  props.setProperty('TERMS', '[]');
  return getData();
}

// ----- 締切まとめ（表にない会社の、ES・エントリー・Webテストなどの締切） -----

// 状態：空（まだ）／提出済み／受けない（その会社の締切はもう出さない）／表に追加
const DEADLINE_HEADER = ['key', '会社名', '何の締切', '締切', '状態', '件名', 'メール', '送信元', '選考種別', '別名・ドメイン', 'メールの日時', '最初のメールの日時', '決めた日時'];

function readDeadlines(ss) {
  const sheet = sheetWithHeader(ss, CONFIG.DEADLINE_SHEET, DEADLINE_HEADER);
  const time = v => (v instanceof Date ? v.getTime() : Number(v || 0));
  const list = sheet.getDataRange().getValues().slice(1).filter(r => r[0]).map(r => ({
    key: String(r[0]), company: String(r[0]).split('|')[0], name: String(r[1]), label: String(r[2]), when: r[3] instanceof Date ? r[3] : null,
    status: String(r[4] || '').replace(/^出した$/, '提出済み'), subject: String(r[5]), url: String(r[6]), sender: String(r[7]), kind: String(r[8]), alias: String(r[9] || ''), // 前の版の「出した」は「提出済み」
    mailAt: time(r[10]), firstAt: time(r[11]), decidedAt: time(r[12]),
  }));
  return { sheet, list };
}

function saveDeadlines(sheet, list) {
  const safe = v => (typeof v === 'string' && /^[=+\-@]/.test(v) ? "'" + v : v);
  const date = t => (t ? new Date(t) : '');
  const rows = list.map(x => [x.key, safe(x.name), x.label, x.when || '', x.status, safe(x.subject), x.url, x.sender, x.kind, safe(x.alias), date(x.mailAt), date(x.firstAt), date(x.decidedAt)]);
  sheet.getRange(1, 1, 1, DEADLINE_HEADER.length).setValues([DEADLINE_HEADER]);
  sheet.getRange(2, 1, Math.max(1, sheet.getLastRow() - 1), DEADLINE_HEADER.length).clearContent();
  if (rows.length) sheet.getRange(2, 1, rows.length, DEADLINE_HEADER.length).setValues(rows);
}

/**
 * 「締切まとめ」シートを作り直す。会社・選考種別・何の締切ごとに1行で、いちばん新しいメールの締切（延長されたら新しい日付）。
 *   - 提出の確認（「ES提出完了」「エントリー受付完了」）が、最初の案内より後に届いたら「提出済み」
 *   - 「提出済み」「受けない」「表に追加」は残す。「受けない」「表に追加」の会社の新しい締切も、同じ状態にする
 * 返り値は、まだ出していない、これからの締切の数
 */
function writeDeadlines(ss, found, submitted, now) {
  const { sheet, list } = readDeadlines(ss);
  const old = new Map(list.map(x => [x.key, x]));
  // 「受けない」会社の新しい締切も受けない（会社のキーか、画面でまとめる名前が同じなら）
  const companyStatus = new Map(list.filter(x => x.status === '受けない' || x.status === '表に追加')
    .flatMap(x => [[x.company, x.status], ['name:' + companyKey(x.name), x.status]]));
  const items = new Map();
  const sorted = found.slice().sort((a, b) => a.date - b.date);
  // 同じ会社のメール（会社名・アドレスの中の会社名などのどれかが同じ：JALグループ と 日本航空 は jal@ と jal_j@）は、
  // いちばん前のメールの会社として1つにまとめる
  const parent = new Map(), first = new Map();
  const root = t => { while (parent.get(t) !== t) t = parent.get(t); return t; };
  // 送信元だけ（会社名がわからない）のときは、同じ送信元どうしだけ
  const keysOf = f => {
    const ks = candidateTokens(f).filter(t => t !== f.sender);
    if (candidateNameKey(f) !== f.sender) ks.push('key:' + candidateNameKey(f));
    return ks.length ? ks : ['sender:' + f.sender];
  };
  // 提出済み・予約済みのメールの会社（締切のメールと同じ会社なら、その会社のキー）
  const companyOf = f => { const k = keysOf(f).find(t => parent.has(t)); return k ? candidateNameKey(first.get(root(k))) : candidateNameKey(f); };
  sorted.forEach(f => {
    const ks = keysOf(f);
    ks.forEach(k => { if (!parent.has(k)) parent.set(k, k); });
    ks.forEach(k => { const a = root(ks[0]), b = root(k); if (a !== b) parent.set(b, a); });
  });
  sorted.forEach(f => { const r = root(keysOf(f)[0]); if (!first.has(r)) first.set(r, f); });
  for (const f of sorted) {
    const lead = first.get(root(keysOf(f)[0]));
    const company = candidateNameKey(lead);
    const label = f.entry ? 'エントリー' : f.meeting ? f.what : f.step; // f.what は「面談の予約」など
    // キーはそのメールの会社のまま（日本航空のESとJALグループのESは、別の締切として両方出す）
    const key = candidateNameKey(f) + '|' + kindGroup(f.kind) + '|' + label;
    const o = old.get(key), prev = items.get(key);
    // 表の選考が終わった会社は、表と同じ名前。ほかは部署の名前を除いた会社名（「アクセンチュア 同志社大学リクルーターチーム」→「アクセンチュア」）
    const name = lead.listName || f.listName || cleanCompanyName(shortName(lead.company)) || lead.sender;
    items.set(key, {
      key, company, name, label, when: f.when, subject: f.subject, url: f.url, sender: f.sender, kind: f.kind, alias: candidateAlias(f, name),
      mailAt: f.date.getTime(), firstAt: prev ? prev.firstAt : f.date.getTime(),
      status: o ? o.status : companyStatus.get(company) || companyStatus.get('name:' + companyKey(name)) || '', decidedAt: o ? o.decidedAt : 0,
    });
  }
  for (const s of submitted) {
    const company = companyOf(s), cleaned = companyKey(cleanCompanyName(shortName(s.company)));
    for (const x of items.values()) {
      if (x.status || s.date.getTime() < x.firstAt) continue;
      // 面談などの予約が終わった（日程が決まった）：その会社の「面談の予約」は予約済み
      if (s.type === '面談') {
        if (x.label === s.what + 'の予約' && (x.company === company || companyKey(x.name) === cleaned)) { x.status = '予約済み'; x.decidedAt = s.date.getTime(); }
        continue;
      }
      // 提出済みは、そのメールの会社の締切だけ（JALグループのESを出しても、日本航空のESは残す）
      if (!x.key.startsWith(candidateNameKey(s) + '|')) continue;
      if (s.entry ? x.label === 'エントリー' || x.label === 'ES' : x.label === s.step) { x.status = '提出済み'; x.decidedAt = s.date.getTime(); }
    }
  }
  // 決めたもの（受けない会社は、ずっと。ほかは締切から30日）は、メールが見つからなくなっても残す
  for (const x of list) {
    if (!items.has(x.key) && x.status && (x.status === '受けない' || !x.when || x.when.getTime() > now.getTime() - 30 * 864e5)) items.set(x.key, x);
  }
  const all = [...items.values()].sort((a, b) => (a.when ? a.when.getTime() : 0) - (b.when ? b.when.getTime() : 0));
  saveDeadlines(sheet, all);
  return all.filter(x => !x.status && x.when && x.when > now).length;
}

/**
 * 画面の締切まとめのボタン（その会社の締切は全部消える）
 *   - 提出済み：選考が始まったので、表に行を足して追いかける（次の選考は、出したものの結果待ち）
 *   - 受けない：その会社の締切は、もう出さない
 *   - 今回は受けない：その締切だけ消す（同じ会社のほかの締切・あとから来る締切は出す）
 */
function resolveDeadline(key, action) {
  // 予約済み：面談などの予約をした（その締切だけ消す。選考ではないので、表には入れない）
  if (!['提出済み', '受けない', '今回は受けない', '予約済み'].includes(action)) throw new Error('わからない操作です: ' + action);
  const ss = getSpreadsheet();
  const { sheet, list } = readDeadlines(ss);
  const x = list.find(r => r.key === key);
  if (!x) return getData();
  const at = new Date().getTime();
  // 「この会社」は、画面で1つにまとめた会社（同じ名前の会社）全部
  const same = r => r.company === x.company || companyKey(r.name) === companyKey(x.name);
  for (const r of action === '今回は受けない' || action === '予約済み' ? [x] : list.filter(same)) { r.status = action; r.decidedAt = at; }
  saveDeadlines(sheet, list);
  if (action === '提出済み') addTableRow(ss, x.name, x.kind, x.alias, x.label);
  return getData();
}

// ===== 予定の記録：過ぎた面接・GD・面談・ESの提出などを1行ずつ残す（カレンダーの過ぎた日に出す） =====
// 会社一覧の行は、選考が進むと前の日時が消えるので、ここに残す。結果のメールが来たら「通過」「NG」なども書き足す。
// メールが古くなって読み込み済みから消えても、記録は残る。HISTORY_MAX を超えたら古いものから消す

const HISTORY_HEADER = ['key', '日時', '会社名', '選考種別', '何', '種類', '結果', '結果の日時', 'メール'];

function readHistory(ss) {
  const sheet = sheetWithHeader(ss, CONFIG.HISTORY_SHEET, HISTORY_HEADER);
  const list = sheet.getDataRange().getValues().slice(1).filter(r => r[0]).map(r => ({
    key: String(r[0]), date: Number(r[1]), name: String(r[2]), kind: String(r[3]), what: String(r[4]), type: String(r[5]),
    result: String(r[6] || ''), resultAt: Number(r[7] || 0), mail: String(r[8] || ''),
  }));
  return { sheet, list };
}

function saveHistory(sheet, list) {
  const safe = v => (typeof v === 'string' && /^[=+\-@]/.test(v) ? "'" + v : v);
  const rows = list.slice().sort((a, b) => a.date - b.date).slice(-CONFIG.HISTORY_MAX)
    .map(x => [x.key, x.date, safe(x.name), x.kind, x.what, x.type, x.result, x.resultAt || '', x.mail]);
  const old = sheet.getLastRow() - 1;
  if (old > 0) sheet.getRange(2, 1, old, HISTORY_HEADER.length).clearContent();
  if (rows.length) sheet.getRange(2, 1, rows.length, HISTORY_HEADER.length).setValues(rows);
}

/**
 * 記録に足す・直す。
 *   - 面接・GDなどの日程が決まったメールで、もう過ぎたもの／会社一覧の行の過ぎた日程／結果待ちにした行の、終わった選考（面接の日時・提出の日時）
 *   - 面談・座談会などで、もう過ぎたもの
 *   - ESの提出・Webテストの受検の確認
 * 同じ会社・同じ選考種別・同じこと（1次面接など）で日付が45日以内なら同じ予定（日程の変更は新しい日付に直す）。離れていれば別の選考の予定。
 * そのあと、通過・お見送り・内定などのメールで、その前のいちばん近い記録に結果を書く
 */
function writeHistory(ss, table, findings, appts, now) {
  const { sheet, list } = readHistory(ss);
  const before = JSON.stringify(list);
  // 同じ会社（「株式会社」の有無などはちがっても）・同じ日時の記録は1つだけ（前の版で2つできたものは、結果があるほうを残す）
  const atKey = h => companyKey(h.name) + '|' + h.date;
  const firstAt = new Map();
  list.slice().sort((a, b) => (b.result ? 1 : 0) - (a.result ? 1 : 0)).forEach(h => {
    if (firstAt.has(atKey(h))) list.splice(list.indexOf(h), 1); else firstAt.set(atKey(h), h);
  });
  const t = now.getTime();
  const submitWhat = step => step + (step === 'Webテスト' || step === 'AI面接' ? 'の受検' : 'の提出');
  const put = x => {
    const base = x.name + '|' + x.kind + '|' + x.what;
    const same = list.find(h => h.key.split('#')[0] === base && Math.abs(h.date - x.date) <= 45 * 864e5) || list.find(h => atKey(h) === atKey(x));
    // 会社一覧の行から足すもの（weak）は、メールから入れた記録があれば日付を変えない
    if (same) { if (!x.weak) { same.date = x.date; if (x.mail) same.mail = x.mail; } return; }
    const d = new Date(x.date);
    const key = list.some(h => h.key === base) ? base + '#' + d.getFullYear() + String(d.getMonth() + 1).padStart(2, '0') + String(d.getDate()).padStart(2, '0') : base;
    list.push({ key, date: x.date, name: x.name, kind: x.kind, what: x.what, type: x.type, result: '', resultAt: 0, mail: x.mail || '' });
  };
  // メールの会社の、会社一覧の行（同じ選考種別の行があればそれ）
  const rowOf = f => {
    const rs = rowsForMail(table.rows, f);
    const same = rs.filter(r => kindGroup(r.kind) === f.kind);
    return (same.length ? same : rs)[0] || null;
  };
  const sorted = findings.slice().sort((a, b) => a.date - b.date);
  // キャンセルした予定：予定のメールのあと、その日時より前に、同じ会社のキャンセルの連絡が来たもの。記録にしない（前の版で入った記録も消す）
  const cancels = sorted.filter(f => f.type === '取消');
  const cancelled = f => !!f.when && cancels.some(g => g.date > f.date && g.date < f.when && rowOf(g) === rowOf(f));
  for (const f of sorted) {
    const r = (f.type === '予定' || f.type === '提出済') && rowOf(f);
    if (!r) continue;
    if (f.type === '予定' && f.when && cancelled(f)) {
      const gone = list.filter(h => h.date === f.when.getTime() && companyKey(h.name) === companyKey(r.name));
      gone.forEach(h => list.splice(list.indexOf(h), 1));
      continue;
    }
    if (f.type === '予定' && f.step && f.when && f.when.getTime() < t) put({ name: r.name, kind: kindGroup(r.kind), what: f.step, type: '選考', date: f.when.getTime(), mail: f.url });
    if (f.type === '提出済' && SUBMIT_STEPS.includes(f.step)) put({ name: r.name, kind: kindGroup(r.kind), what: submitWhat(f.step), type: '提出', date: f.date.getTime(), mail: f.url });
  }
  for (const a of appts || []) {
    if (!a.when || a.when.getTime() >= t) continue;
    const r = rowOf(a);
    put({ name: r ? r.name : cleanCompanyName(shortName(a.company)) || a.sender, kind: r ? kindGroup(r.kind) : kindGroup(a.kind), what: a.what || '面談', type: '面談', date: a.when.getTime(), mail: a.url });
  }
  for (const r of table.rows) {
    const kind = kindGroup(r.kind);
    if (r.when && r.when.getTime() < t && r.step && r.step !== WAITING && (r.slot || defaultSlot(r.step)) === EVENT) {
      put({ name: r.name, kind, what: r.step, type: '選考', date: r.when.getTime(), mail: r.mail, weak: true });
    }
    // 結果待ちにした行：終わった選考（面接なら面接の日時、ESなどなら提出の日時）
    const o = r.owned || {};
    if (r.step === WAITING && o.done && o.at && o.at < t && !FINAL_STATES.includes(r.state)) { // 結果が出た行の at は結果の日時なので使わない
      put(SUBMIT_STEPS.includes(o.done) ? { name: r.name, kind, what: submitWhat(o.done), type: '提出', date: o.at, mail: r.mail, weak: true }
        : { name: r.name, kind, what: o.done, type: '選考', date: o.at, mail: r.mail, weak: true });
    }
  }
  // 結果：そのメールより前の、いちばん近い記録（面談は選考ではないので除く）。同じメールでもう書いてあれば、そのまま
  for (const f of sorted) {
    if (!(f.type === '結果' || f.type === '通過' || f.passed)) continue;
    const r = rowOf(f);
    if (!r) continue;
    const at = f.date.getTime();
    const result = f.type === '結果' ? (f.state === 'インターン参加決定' ? '参加決定' : f.state) : '通過';
    const h = list.filter(x => x.name === r.name && x.kind === kindGroup(r.kind) && x.type !== '面談' && x.date <= at && (!x.result || x.resultAt === at))
      .sort((a, b) => b.date - a.date)[0];
    if (h) { h.result = result; h.resultAt = at; }
  }
  // 選考の流れから「通過」（通過のメールを送らず、次の選考の案内だけ来る会社が多いため）。同じ会社・同じ選考種別で：
  //   1. その日より後に、選考が進んだ連絡（次の選考の日程確定・予約・日程調整のお願い・通過）が来た（サイバーエージェントの「選考結果のご連絡」→ 次の予約など）
  //   2. あとに、別の選考の記録がある（1次面接 → 2次面接）
  //   3. 会社一覧の行が、もっと先の段階（2次面接など、番号のある段階どうしで比べる）に進んでいる
  const stepOfRec = h => (h.type === '提出' ? h.what.replace(/の(提出|受検)$/, '') : h.what);
  const numbered = s => /^(\d+次|最終)/.test(s || '');
  const signals = new Map(); // 会社｜選考種別 → [{ mail（届いた日時）, when（何の日時のことか） }]
  for (const f of sorted) {
    if (!(f.type === '予定' || f.type === '調整' || f.type === '通過' || f.passed) || (f.type === '予定' && cancelled(f))) continue;
    const r = rowOf(f);
    if (!r) continue;
    const k = companyKey(r.name) + '|' + kindGroup(r.kind);
    if (!signals.has(k)) signals.set(k, []);
    signals.get(k).push({ mail: f.date.getTime(), when: f.type === '予定' && f.when ? f.when.getTime() : f.date.getTime() });
  }
  const rowRankOf = new Map(); // 会社｜選考種別 → 会社一覧の行の今の段階（結果待ちなら、結果を待っている段階）
  table.rows.forEach(r => {
    const k = companyKey(r.name) + '|' + kindGroup(r.kind);
    const rank = stepRank(r.step === WAITING ? (r.owned && r.owned.done) || '' : r.step);
    rowRankOf.set(k, Math.max(rowRankOf.has(k) ? rowRankOf.get(k) : -1, rank));
  });
  const flows = new Map();
  list.filter(h => h.type !== '面談').forEach(h => {
    const k = companyKey(h.name) + '|' + h.kind;
    if (!flows.has(k)) flows.set(k, []);
    flows.get(k).push(h);
  });
  for (const [k, hs] of flows) {
    hs.sort((a, b) => a.date - b.date);
    hs.forEach((h, i) => {
      if (h.result) return;
      // 1. その日より後に届いた、もっと後のことについての連絡（同じ予定のリマインドなどは数えない）
      const sig = (signals.get(k) || []).filter(s => s.mail > h.date && s.when > h.date + 3600e3).sort((a, b) => a.mail - b.mail)[0];
      if (sig) { h.result = '通過'; h.resultAt = sig.mail; return; }
      // 2. あとに別の選考の記録
      const later = hs.slice(i + 1).find(x => x.type === '選考' && x.date > h.date + 3600e3);
      if (later) { h.result = '通過'; h.resultAt = later.date; return; }
      // 3. 会社一覧が、もっと先の番号の段階
      const rank = stepRank(stepOfRec(h));
      if (numbered(stepOfRec(h)) && rank >= 0 && (rowRankOf.has(k) ? rowRankOf.get(k) : -1) > rank) { h.result = '通過'; h.resultAt = h.date; }
    });
  }
  if (JSON.stringify(list) !== before) saveHistory(sheet, list);
}

/** 会社を非表示にしたとき：その会社の記録も消す */
function deleteHistory(ss, name) {
  if (!ss.getSheetByName(CONFIG.HISTORY_SHEET)) return;
  const { sheet, list } = readHistory(ss);
  const keep = list.filter(h => companyKey(h.name) !== companyKey(name));
  if (keep.length !== list.length) saveHistory(sheet, keep);
}

/** 設定の「非表示にしたもの」の締切の「戻す」：この締切だけ（今回は受けない）か、その会社の締切を全部（受けない）、また締切まとめに出す */
function restoreDeadline(key) {
  const ss = getSpreadsheet();
  const { sheet, list } = readDeadlines(ss);
  const x = list.find(r => r.key === key);
  if (!x) return getData();
  const same = r => r.company === x.company || companyKey(r.name) === companyKey(x.name);
  for (const r of x.status === '受けない' ? list.filter(r => same(r) && r.status === '受けない') : [x]) { r.status = ''; r.decidedAt = 0; }
  saveDeadlines(sheet, list);
  return getData();
}

/**
 * 「面接」とだけ書いてあるメールが、行のどの面接のことか。
 *   - 行が「2次面接」なら2次面接。ただし、今の面接の日程より後の、これからの日時なら次の面接（3次面接）
 *   - 行が面接のあとの「結果待ち」なら、これからの日時は次の面接。もう過ぎた日時は終わった面接なので null
 *   - 前の表で通過にチェックがあった面接の日時より前（または同じ）なら、終わった面接なので null
 *   - それ以外は「面接」のまま
 */
function interviewFor(f, row) {
  const isInterview = s => /^([1-4]次(面接|選考)|最終面接)$/.test(s || '');
  const after = t => f.when.getTime() > t + CONFIG.EVENT_HOURS * 3600e3;
  const future = f.when > new Date();
  if (row.owned && row.owned.passedAt && !after(row.owned.passedAt)) return null;
  if (isInterview(row.step)) {
    return future && row.slot === EVENT && row.when && after(row.when.getTime()) ? (NEXT_AFTER_PASS[row.step] || '面接') : row.step;
  }
  if (row.step === WAITING && row.owned && isInterview(row.owned.done)) {
    return future && after(row.owned.at || 0) ? (NEXT_AFTER_PASS[row.owned.done] || '面接') : null;
  }
  return '面接';
}

// ----- 確認待ち・更新の記録 -----

const REVIEW_HEADER = ['id', 'メールの日時', '会社（メールから）', '候補の行', '提案：次の選考', '提案：日時・期限', '提案：状況', '理由', 'メール', '状態', '提案：締切/日程'];

function sheetWithHeader(ss, name, header) {
  let sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
    sheet.getRange(1, 1, 1, header.length).setValues([header]).setFontWeight('bold');
    sheet.setFrozenRows(1);
  }
  return sheet;
}

function readReview(ss) {
  const sheet = sheetWithHeader(ss, CONFIG.REVIEW_SHEET, REVIEW_HEADER);
  const list = sheet.getDataRange().getValues().slice(1).filter(r => r[0]).map(r => ({
    id: String(r[0]), date: r[1], company: r[2], rows: String(r[3]).split(' / ').filter(s => s),
    step: r[4], when: r[5] instanceof Date ? r[5] : (r[5] ? new Date(r[5]) : null), state: r[6], reason: r[7], url: r[8], status: r[9] || '未確認',
    slot: String(r[10] || ''),
  }));
  return { sheet, list, ids: new Set(list.map(x => x.id)), dirty: false };
}

/** 同じ行・同じ提案は1回だけ出す（却下したものも、もう出さない） */
function addReview(review, f, rows, p, reason) {
  const keys = rows.map(rowKey);
  const id = [keys.join('+'), p.step || '', p.when ? p.when.getTime() : '', p.state || '', p.slot || ''].join('|');
  if (review.ids.has(id)) return;
  review.ids.add(id);
  review.list.push({ id, date: f.date, company: f.company, rows: keys, step: p.step || '', slot: p.slot || '', when: p.when || null, state: p.state || '', reason, url: f.url, status: '未確認' });
  review.dirty = true;
}

function writeReview(review) {
  if (!review.dirty) return;
  const safe = v => (typeof v === 'string' && /^[=+\-@]/.test(v) ? "'" + v : v);
  const rows = review.list.map(x => [x.id, x.date, safe(x.company), x.rows.join(' / '), x.step, x.when || '', x.state, x.reason, x.url, x.status, x.slot || '']);
  review.sheet.getRange(2, 1, Math.max(1, review.sheet.getLastRow() - 1), REVIEW_HEADER.length).clearContent();
  if (rows.length) review.sheet.getRange(2, 1, rows.length, REVIEW_HEADER.length).setValues(rows);
}

/** 「更新の記録」シート：メールごとに、どの行と判断して何を書いたか（新しいものが上） */
function writeTrace(ss, trace) {
  const header = ['メールの日時', '会社（メールから）', '件名', '選考種別（メールから）', '結果', 'くわしく'];
  const sheet = sheetWithHeader(ss, CONFIG.TRACE_SHEET, header);
  const rows = trace.slice().sort((a, b) => b[0] - a[0]).slice(0, 500).map(r => r.map(v => (typeof v === 'string' && /^[=+\-@]/.test(v) ? "'" + v : v)));
  sheet.getRange(2, 1, Math.max(1, sheet.getLastRow() - 1), header.length).clearContent();
  if (rows.length) sheet.getRange(2, 1, rows.length, header.length).setValues(rows);
}

// ===== 更新（ここから全部が動く） =====

/** メールを読んで表を更新する。full のときは DAYS 日ぶんをGmailから全部読み直す */
function update(full) {
  const ss = getSpreadsheet();
  const now = new Date();
  const table = readTable(ss);
  // 「次の選考」「締切/日程」の選択肢をそろえる（前に作った表には「1次選考」「日程調整」「確定待ち」などがないため）
  const n = Math.max(table.sheet.getMaxRows() - 1, 1);
  const list = l => SpreadsheetApp.newDataValidation().requireValueInList(l, true).setAllowInvalid(true).build();
  table.sheet.getRange(2, table.cols.step, n, 1).setDataValidation(list(STEP_LIST));
  if (table.cols.slot) table.sheet.getRange(2, table.cols.slot, n, 1).setDataValidation(list(SLOT_LIST));
  const blocked = readBlocked(ss);
  const { mails, info, stopped } = collectMails(ss, table.rows, !!full, now, blocked);
  const findings = [], unread = [];
  const seen = new Set();
  let me = '';
  try { me = String(Session.getEffectiveUser().getEmail() || '').toLowerCase(); } catch (e) { me = ''; }
  const replies = new Map(); // スレッドごとの、あなたが最後に返信した日時（日程調整に返したかを見る）
  const myMails = []; // あなたが送ったメール（頼まれた書類を返信で送ったかを見る）
  const tasks = [], receipts = []; // 頼まれごと（履歴書の提出など）と、その受け取りの連絡
  const appts = []; // 日時が決まった面談・座談会など（締切まとめの「面談の予約」を予約済みにするため）
  for (const d of mails) {
    // 自分が送ったメール（会社への返信など）は読まない。返信した日時だけ覚えておく
    const addr = mailInfo(d).addr;
    if ((me && addr === me) || (/^(re|fw|fwd)\s*[:：]/i.test(d.subject) && FREE_MAIL.test(addr.split('@')[1] || ''))) {
      replies.set(d.thread, Math.max(replies.get(d.thread) || 0, d.date.getTime()));
      myMails.push(d);
      continue;
    }
    // 転送などで同じメールが2通あるときは1通だけ読む
    const key = d.from + '|' + d.subject + '|' + Math.floor(d.date.getTime() / 60000);
    if (seen.has(key)) continue;
    seen.add(key);
    const f = readMail(d, now);
    // 面談・座談会などは、選考の表ではなく「タスク」シートに予定として入れる
    if (f && f.type === '面談') { tasks.push(Object.assign({ appt: true }, f)); appts.push(f); }
    else if (f) findings.push(f); else unread.push(mailInfo(d));
    // 面談などの予約の締切：表にある会社はタスク「面談の予約」（表にない会社は締切まとめ：applyFindings）
    if (f && f.meeting) tasks.push(Object.assign({}, f, { item: f.what, due: f.when, rel: '', days: 0, thread: d.thread, detail: '' }));
    tasksOf(d).forEach(t => tasks.push(t));
    receiptsOf(d).forEach(r => receipts.push(r));
  }
  const result = applyFindings(ss, table, findings, now, unread, replies, appts);
  // やること（履歴書の提出など）は、表を書いたあとに（面接の日時から期限を計算するため）
  result.tasks = applyTasks(ss, table, tasks, receipts, myMails, now);
  // 過ぎた予定・提出と、その結果を記録に残す（会社一覧を書いたあとの行から）
  writeHistory(ss, readTable(ss), findings, appts, now);
  // 途中でやめたときは前回の更新の日時のままにして、次の更新で同じ範囲の残りを読む
  if (!stopped) PropertiesService.getUserProperties().setProperty('LAST_RUN', String(now.getTime()));
  result.stopped = stopped;
  Logger.log('メール' + mails.length + '通（' + info + '）から、' + result.written + '行を更新、確認待ち' + result.pending + '件、新しい会社の候補' + result.candidates + '件、締切まとめ' + result.deadlines + '件: ' + ss.getUrl());
  return result;
}

/**
 * 表を作り直す（ツールを直したあとに）。Gmailには新しいメールだけ問い合わせ、保存済みのメールは全部読み直して表に当てはめる。
 * いつもの「メールから更新」と同じで、すぐ終わる
 */
function fullUpdate() {
  update(false);
}

/** Gmailに直近 DAYS 日ぶんを問い合わせ直す（保存したメールが足りないと思うときだけ。時間がかかる） */
function rereadGmail() {
  update(true);
}

// ===== 画面（ウェブアプリ） =====

function doGet() {
  const t = HtmlService.createTemplate(PAGE_HTML);
  t.data = JSON.stringify(getData()).replace(/</g, '\\u003c');
  return t.evaluate().setTitle('就活カレンダー').addMetaTag('viewport', 'width=device-width, initial-scale=1');
}

/** 画面に出すもの：これからの締切・予定（表から）、日時が決まっていない行、確認待ち */
function getData() {
  const ss = getSpreadsheet();
  let table;
  try { table = readTable(ss); } catch (e) { return { error: e.message, upcoming: [], undecided: [], waiting: [], reviews: [], candidates: [], deadlines: [], tasks: [], conflicts: [], stats: null, sheetUrl: ss.getUrl() }; }
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const active = table.rows.filter(r => !['NG', '辞退'].includes(r.state));
  // 自動で表に入れた会社（会社名 → 候補のキー）。「自動」の印と「表から外す」に使う
  const candList = ss.getSheetByName(CONFIG.CANDIDATE_SHEET) ? readCandidates(ss).list : [];
  // 新しい選考として足した行（reopen）は、終わった前の行には印を付けない
  const autoOf = new Map(candList.filter(x => x.status === '自動で追加').map(x => [companyKey(x.name), x]));
  const autoKeyOf = r => { const a = autoOf.get(companyKey(r.name)); return a && !(a.reopen && FINAL_STATES.includes(r.state)) ? a.key : ''; };
  // 設定の「表から外した会社」（戻せる）
  const removed = candList.filter(x => x.status === '外した' || x.status === '無視').sort((a, b) => b.decidedAt - a.decidedAt)
    .map(x => ({ key: x.key, name: x.name, at: x.decidedAt ? new Date(x.decidedAt).toISOString() : null }));
  // 結果待ちは、何の結果を待っているか（ツールが結果待ちにした行だけわかる）
  const item = r => ({ key: rowKey(r), name: r.name, kind: r.kind, state: r.state, step: r.step, slot: r.slot, label: stepLabel(r.step, r.slot),
    autoKey: autoKeyOf(r),
    waitFor: r.step === WAITING && r.owned && r.owned.done || '',
    // 結果待ちになってからの日数（ツールが結果待ちにした行だけ。自分で書いた結果待ちは、いつからかわからない）
    waitDays: r.step === WAITING && r.owned && r.owned.step === WAITING && r.owned.at ? Math.round((today.getTime() - new Date(new Date(r.owned.at).setHours(0, 0, 0, 0)).getTime()) / 864e5) : null,
    when: r.when ? r.when.toISOString() : null, mail: r.mail, memo: r.memo, alias: r.alias });
  const upcoming = active.filter(r => r.when && r.when >= today && !['内定'].includes(r.state)).sort((a, b) => a.when - b.when).map(item);
  // 日時が決まっていない（日程の調整待ち・過ぎたまま）と、結果待ちは別の欄に出す
  const pending = active.filter(r => !FINAL_STATES.includes(r.state) && (!r.when || r.when < today));
  // 日程調整（あなたが動く番）を上に。「非表示」にした行（同じ次の選考のあいだ）は、下の「非表示にした会社」に分ける
  const hidden = readHiddenUndecided();
  const isHidden = r => !!hidden[rowKey(r)] && hidden[rowKey(r)].step === r.step;
  const undecidedAll = pending.filter(r => r.step !== WAITING).sort((a, b) => (b.slot === ADJUST) - (a.slot === ADJUST));
  const undecided = undecidedAll.filter(r => !isHidden(r)).map(item);
  const undecidedHidden = undecidedAll.filter(isHidden).sort((a, b) => hidden[rowKey(b)].at - hidden[rowKey(a)].at)
    .map(r => Object.assign(item(r), { hiddenAt: new Date(hidden[rowKey(r)].at).toISOString() }));
  // 結果待ちは、待っている日数の長い順（日数がわからないものは下）
  const waiting = pending.filter(r => r.step === WAITING).map(item)
    .sort((a, b) => (b.waitDays == null ? -1 : b.waitDays) - (a.waitDays == null ? -1 : a.waitDays));
  const reviews = ss.getSheetByName(CONFIG.REVIEW_SHEET) ? readReview(ss).list.filter(x => x.status === '未確認').map(x => ({
    id: x.id, company: x.company, rows: x.rows, step: x.step, slot: x.slot, label: stepLabel(x.step, x.slot),
    when: x.when ? x.when.toISOString() : null, state: x.state, reason: x.reason, url: x.url,
  })) : [];
  // 候補：まだ決めていないもの（未確認）と、自動で表に入れた会社（入れてから2週間。間違っていたら「表から外す」）
  const candidates = ss.getSheetByName(CONFIG.CANDIDATE_SHEET) ? readCandidates(ss).list
    .filter(x => x.status === '未確認' || (x.status === '自動で追加' && now.getTime() - x.decidedAt < 14 * 864e5)).map(x => ({
      key: x.key, name: x.name, kind: x.kind, label: x.label, when: x.when ? x.when.toISOString() : null, subject: x.subject, url: x.url, count: x.count, reopen: x.reopen,
      auto: x.status === '自動で追加',
    })) : [];
  // 締切まとめ：まだ出していない、これからの締切を、会社ごとに1つ（同じ名前の会社はまとめる：PwCコンサルティングとPwCアドバイザリーなど）。
  // 会社の見出しには、いちばん近い締切（key・label・when）と、ほかの締切の数（more）。items にその会社の締切を近い順に
  const deadlines = [];
  // 非表示にした締切（設定の「非表示にしたもの」）：会社ごと全部（受けない）は1社1つ、この締切だけ（今回は受けない）は、まだ過ぎていないものだけ
  const hiddenDeadlines = [];
  if (ss.getSheetByName(CONFIG.DEADLINE_SHEET)) {
    const seen = new Set();
    readDeadlines(ss).list.filter(x => x.status === '受けない' || (x.status === '今回は受けない' && x.when && x.when > now))
      .sort((a, b) => (b.decidedAt || 0) - (a.decidedAt || 0)).forEach(x => {
        const all = x.status === '受けない';
        if (all && seen.has(companyKey(x.name))) return;
        if (all) seen.add(companyKey(x.name));
        hiddenDeadlines.push({ key: x.key, name: x.name, all, label: all ? '' : x.label, when: !all && x.when ? x.when.toISOString() : null,
          at: x.decidedAt ? new Date(x.decidedAt).toISOString() : null });
      });
  }
  if (ss.getSheetByName(CONFIG.DEADLINE_SHEET)) {
    const byCompany = new Map();
    for (const x of readDeadlines(ss).list.filter(x => !x.status && x.when && x.when > now).sort((a, b) => a.when - b.when)) {
      const item = { key: x.key, label: x.label, kind: x.kind, when: x.when.toISOString(), subject: x.subject, mail: x.url };
      const group = companyKey(x.name);
      if (byCompany.has(group)) { const g = byCompany.get(group); g.items.push(item); g.more++; continue; }
      const g = Object.assign({ group, name: x.name, more: 0, ext: true, items: [item] }, item);
      byCompany.set(group, g);
      deadlines.push(g);
    }
  }
  const lastRun = Number(PropertiesService.getUserProperties().getProperty('LAST_RUN') || 0);
  // カレンダーに並べるもの：日時が入っている行（過ぎたものも、その月のマスに出す）
  const events = active.filter(r => r.when && !['内定'].includes(r.state)).sort((a, b) => a.when - b.when).map(item);
  // やること（済でないもの。選考が終わった会社のものは出さない）
  const ended = new Set(table.rows.filter(r => FINAL_STATES.includes(r.state)).map(rowKey));
  const allTasks = taskSheet(ss) ? readTasks(ss).list.filter(x => !x.done && !ended.has((x.tool || {}).row)) : [];
  // 面談・座談会などの予定（「これから」とカレンダーに緑で出す）
  const appts = allTasks.filter(x => (x.tool || {}).appt && x.due).sort((a, b) => a.due - b.due)
    .map(x => ({ key: x.key, name: x.name, what: x.what, when: x.due.toISOString(), end: x.tool.end ? new Date(x.tool.end).toISOString() : null, mail: x.mail, appt: true }));
  const tasks = allTasks.filter(x => !(x.tool || {}).appt)
    .sort((a, b) => (a.due ? a.due.getTime() : Infinity) - (b.due ? b.due.getTime() : Infinity))
    // hold：面接のあとにやること で、面接がまだ始まっていないもの（一覧には出さず、カレンダーの面接の日にだけ出す）
    .map(x => { const t = x.tool || {}; return { key: x.key, name: x.name, what: x.what, when: x.due ? x.due.toISOString() : null, rel: t.rel || '', mail: x.mail, manual: !!t.manual, detail: x.detail || '',
      hold: t.rel === 'after' && (!t.showFrom || t.showFrom > now.getTime()) }; });
  // 予定の重なり：これからの面接・GDなど（日程）と面談で、時間がかぶるか、間が CONFLICT_GAP_MIN 分より短いもの（同じ会社どうしは見ない）。
  // 長さがわからない予定は1時間とみる。重なった予定には、相手の会社名を clash に入れる
  const gap = CONFIG.CONFLICT_GAP_MIN * 60000;
  const span = (x, end) => ({ x, s: new Date(x.when).getTime(), e: end ? new Date(end).getTime() : new Date(x.when).getTime() + 3600e3 });
  const plans = upcoming.filter(x => x.slot === EVENT && new Date(x.when) >= now).map(x => span(x))
    .concat(appts.filter(a => new Date(a.when) >= now).map(a => span(a, a.end))).sort((a, b) => a.s - b.s);
  const conflicts = [];
  const mark = (x, other) => { x.clash = x.clash ? x.clash + '・' + other : other; };
  for (let i = 0; i < plans.length; i++) {
    for (let j = i + 1; j < plans.length; j++) {
      const a = plans[i], b = plans[j];
      if (a.x.name === b.x.name || !(b.s < a.e + gap && a.s < b.e + gap)) continue;
      conflicts.push({ names: [a.x.name, b.x.name], when: new Date(a.s).toISOString(), whens: [a.x.when, b.x.when] });
      mark(a.x, b.x.name);
      mark(b.x, a.x.name);
    }
  }
  // 全体の数字：状況ごとの社数、選考中の行の段階ごとの社数、結果が出た選考の通過率（内定・参加決定 ÷ 内定・参加決定・NG）
  const stage = s => (!s ? '未定' : s === WAITING ? '結果待ち' : /面接|次選考/.test(s) ? '面接' : s === 'ES' ? 'ES' : s === 'GD' ? 'GD' : SUBMIT_STEPS.includes(s) ? 'Webテストなど' : 'その他');
  const count = (list, f) => list.reduce((o, r) => { const k = f(r); o[k] = (o[k] || 0) + 1; return o; }, {});
  const byState = count(table.rows, r => r.state || '選考中');
  const passed = (byState['内定'] || 0) + (byState['インターン参加決定'] || 0);
  const stats = { total: table.rows.length, byState, byStep: count(table.rows.filter(r => !FINAL_STATES.includes(r.state)), r => stage(r.step)),
    passed, decided: passed + (byState['NG'] || 0), deadlineCompanies: deadlines.length };
  // 予定の記録（カレンダーの過ぎた日に出す）と、月ごとのまとめ（数字タブ。今月と前の2か月）
  const historyList = ss.getSheetByName(CONFIG.HISTORY_SHEET) ? readHistory(ss).list : [];
  const history = historyList.map(h => ({ name: h.name, kind: h.kind, what: h.what, type: h.type, result: h.result, when: new Date(h.date).toISOString(), mail: h.mail, hist: true }));
  const monthOf = ms => { const d = new Date(ms); return d.getFullYear() * 12 + d.getMonth(); };
  const thisMonth = monthOf(now.getTime());
  stats.months = [0, 1, 2].map(i => {
    const m = thisMonth - i;
    const inMonth = historyList.filter(h => monthOf(h.date) === m);
    const results = historyList.filter(h => h.result && h.resultAt && monthOf(h.resultAt) === m);
    return { label: (m % 12 + 1) + '月', selections: inMonth.filter(h => h.type === '選考').length, submits: inMonth.filter(h => h.type === '提出').length,
      meetings: inMonth.filter(h => h.type === '面談').length, passed: results.filter(h => h.result === '通過').length,
      offers: results.filter(h => h.result === '内定' || h.result === '参加決定').length, ng: results.filter(h => h.result === 'NG').length };
  });
  // やることを足すときに選べる会社（選考中の行の会社名）
  const companies = [...new Set(table.rows.filter(r => !FINAL_STATES.includes(r.state)).map(r => r.name))];
  // 「会社を追加」の選択肢
  const choices = { kinds: KIND_LIST, steps: STEP_LIST, slots: SLOT_LIST, states: STATE_LIST };
  // 会社タブ：表の会社を全部（選考中 → 内定・参加決定 → NG・辞退）。編集するときの元の値にも使う
  const order = r => (!FINAL_STATES.includes(r.state) ? 0 : ['NG', '辞退'].includes(r.state) ? 2 : 1);
  const companiesAll = table.rows.slice().sort((a, b) => order(a) - order(b)).map(item);
  return { choices, conflicts, stats, companiesAll, removed, hiddenDeadlines, history, blockList: blockList(ss), waitWarnDays: CONFIG.WAIT_WARN_DAYS, upcoming, undecided, undecidedHidden, waiting, reviews, candidates, deadlines, events, tasks, appts, companies, sheetUrl: ss.getUrl(), lastRun: lastRun ? new Date(lastRun).toISOString() : null, warnDays: CONFIG.WARN_DAYS };
}

/** 画面の「メールから更新」 */
function refreshFromWeb(full) {
  let result;
  try {
    result = update(!!full);
  } catch (e) {
    if (/gmail/i.test(String(e.message))) throw new Error('Gmailを使える1日の回数の上限に達しました。しばらく（最大24時間ほど）たってから、もう一度お試しください。');
    throw e;
  }
  const data = getData();
  if (result && result.stopped) data.notice = 'メールが多いので、途中まで読んで反映しました。もう一度「メールから更新」を押すと続きを読みます。';
  return data;
}

/** 画面の確認待ち：反映（accept）か却下。候補の行がいくつかあるときは key で選ぶ */
function resolveReview(id, accept, key) {
  const ss = getSpreadsheet();
  const review = readReview(ss);
  const x = review.list.find(r => r.id === id);
  if (!x) return getData();
  if (accept) {
    const table = readTable(ss);
    const row = table.rows.find(r => rowKey(r) === (key || x.rows[0]));
    if (row) {
      const set = (k, v) => table.sheet.getRange(row.r, table.cols[k]).setValue(v);
      const owned = Object.assign({}, row.owned || {}, { at: new Date(x.date).getTime() });
      if (x.step) { set('step', x.step); owned.step = x.step; }
      if (x.step && table.cols.slot) { set('slot', x.slot || ''); owned.slot = x.slot || ''; }
      if (x.when) { set('when', x.when); owned.when = x.when.getTime(); } else if (x.step === WAITING) { set('when', ''); owned.when = null; }
      if (x.state) { set('state', x.state); owned.state = x.state; } else if (!row.state) set('state', '選考中');
      set('owned', JSON.stringify(owned));
      set('mail', x.url);
    }
  }
  x.status = accept ? '反映' : '却下';
  review.dirty = true;
  writeReview(review);
  return getData();
}

